// 중1·중2 영어(입시) 단원 콘텐츠
ENG.add('m1', 'be동사와 일반동사 현재', {
  sub: '주어에 맞는 현재형 동사 고르기',
  kw: ['be동사', 'am/are/is', '일반동사', '3인칭 단수', '-s/-es', 'do/does', '부정문', '의문문'],
  sections: [
    { h: 'be동사의 현재형',
      p: 'be동사는 "~이다, ~에 있다"라는 뜻이다. 현재형은 주어에 따라 <span class="hl">am, are, is</span> 중 하나를 쓴다. 주어가 I이면 am, you와 복수이면 are, 3인칭 단수(he, she, it, Tom 등)이면 is를 쓴다.',
      table: { head: ['주어', 'be동사', '줄임말'], rows: [['I', 'am', "I'm"], ['you / we / they / 복수 명사', 'are', "you're, we're, they're"], ['he / she / it / 단수 명사', 'is', "he's, she's, it's"]], cap: 'be동사 현재형 정리' },
      ex: [["I am a middle school student.", "나는 중학생이다."], ["My parents are in the kitchen.", "우리 부모님은 부엌에 계신다."], ["The cat is under the table.", "고양이는 탁자 밑에 있다."]],
      tip: 'Tom and I처럼 두 사람이 and로 묶이면 복수이므로 are를 쓴다.' },
    { h: '일반동사 현재형과 3인칭 단수',
      p: 'be동사가 아닌 동사(go, like, play 등)를 일반동사라고 한다. 주어가 <b>3인칭 단수</b>이고 현재일 때는 동사 끝에 <span class="hl">-s나 -es</span>를 붙인다. 그 밖의 주어에는 동사원형을 그대로 쓴다.',
      table: { head: ['동사 끝', '만드는 법', '예'], rows: [['대부분', '+s', 'like → likes, play → plays'], ['-s, -sh, -ch, -x, -o', '+es', 'wash → washes, watch → watches, go → goes'], ['자음 + y', 'y를 i로 고치고 +es', 'study → studies, cry → cries'], ['모음 + y', '+s', 'play → plays, buy → buys'], ['have', '불규칙', 'have → has']], cap: '3인칭 단수 현재형 만드는 법' },
      ex: [["She watches TV after dinner.", "그녀는 저녁 식사 후에 TV를 본다."], ["My brother studies Chinese.", "우리 형은 중국어를 공부한다."], ["They play soccer on Sundays.", "그들은 일요일마다 축구를 한다."]],
      warn: 'play처럼 모음 뒤에 y가 오면 plaies가 아니라 plays이다.' },
    { h: '부정문과 의문문',
      p: 'be동사 문장은 be동사 뒤에 not을 붙여 부정문을 만들고, 주어와 be동사의 자리를 바꾸어 의문문을 만든다. 일반동사 문장은 <span class="hl">don\'t / doesn\'t + 동사원형</span>으로 부정하고, <span class="hl">Do / Does + 주어 + 동사원형 ~?</span>으로 묻는다.',
      table: { head: ['구분', 'be동사', '일반동사'], rows: [['부정문', 'He is not(isn\'t) tired.', 'He does not(doesn\'t) like milk.'], ['의문문', 'Is he tired?', 'Does he like milk?'], ['대답', 'Yes, he is. / No, he isn\'t.', 'Yes, he does. / No, he doesn\'t.']] },
      ex: [["Are you hungry? — No, I'm not.", "너 배고프니? — 아니, 안 고파."], ["Does Mina have a pet? — Yes, she does.", "미나는 애완동물이 있니? — 응, 있어."]],
      warn: 'does를 쓰면 뒤의 동사는 반드시 원형이다. Does he likes (×) → Does he like (○)' },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I ___ a student.', o: ['am', 'is', 'are', 'be'], a: 0, why: '주어가 I이므로 am을 쓴다. is는 3인칭 단수, are는 you와 복수 주어에 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>She ___ to school by bus every day.', o: ['go', 'goes', 'going', 'is go'], a: 1, why: '주어가 3인칭 단수이고 현재의 습관이므로 goes를 쓴다. go는 -o로 끝나서 -es를 붙인다.' },
    { lv: 1, q: 'watch의 3인칭 단수 현재형으로 알맞은 것은?', o: ['watchs', 'watchies', 'watches', 'watching'], a: 2, why: '-ch로 끝나는 동사는 -es를 붙인다. watching은 -ing형이다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>My brother ___ not like carrots.', o: ['do', 'is', 'are', 'does'], a: 3, why: '일반동사 like의 부정문이고 주어가 3인칭 단수이므로 does not을 쓴다. be동사 is는 일반동사와 함께 쓰지 않는다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>___ your parents at home now?', o: ['Is', 'Are', 'Do', 'Does'], a: 1, why: 'at home(집에 있다)은 be동사로 표현하고, 주어 your parents가 복수이므로 Are를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>Mina ___ English every evening.', o: ['study', 'studys', 'studies', 'studyes'], a: 2, why: '자음 + y로 끝나는 study는 y를 i로 고치고 -es를 붙여 studies가 된다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['He has two cats.', 'They are my friends.', "She don't eat breakfast.", 'Tom and I are in the same class.'], a: 2, why: '주어 She가 3인칭 단수이므로 doesn\'t eat이 맞다. Tom and I는 복수라서 are가 맞다.' },
    { lv: 3, q: '질문에 대한 대답으로 알맞은 것은?<br>Does your sister play the piano?', o: ['Yes, she does.', 'Yes, she is.', "No, she don't.", "No, she isn't."], a: 0, why: 'Does로 물으면 does / doesn\'t로 답한다. is로 답하거나 she don\'t로 쓰면 틀린다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['Is he live in Seoul?', 'Does he lives in Seoul?', 'Do he live in Seoul?', 'Does he live in Seoul?'], a: 3, why: '일반동사 live의 의문문이고 주어가 he이므로 Does he + 동사원형(live)을 쓴다.' },
    { lv: 4, q: `다음 글을 읽고 물음에 답하시오.<div class="passage">My name is Jiho. I am fourteen years old. I live in Busan with my family. My father is a cook, and my mother teaches math at a high school. My little sister, Yuna, is eight. She loves animals. Every morning, she feeds our dog, Coco. On weekends, we walk Coco on the beach together.</div>Yuna가 매일 아침 하는 일은?`, o: ['수학을 가르친다', '개에게 먹이를 준다', '해변을 산책한다', '요리를 한다'], a: 1, why: 'Every morning, she feeds our dog, Coco.라고 했다. 해변 산책은 주말에 가족이 함께 하는 일이다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Ben <u>①&nbsp;is</u> my best friend. He <u>②&nbsp;lives</u> next to my house, so we often meet. He <u>③&nbsp;have</u> a big brown dog, Max. After school, we <u>④&nbsp;walk</u> Max in the park. Max is very friendly. He runs fast and loves children. I don't have a pet, so I really like Max.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '주어 He가 3인칭 단수이므로 have가 아니라 has를 써야 한다. ④는 주어가 we라서 walk가 맞다.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Sora gets up at six thirty every morning. She doesn't eat much for breakfast. She usually has a banana and a glass of milk. Her school starts at eight forty, but she gets there early. She likes to read books in the classroom before her friends come. After school, she takes a dance class twice a week.</div>`, o: ['소라는 6시 30분에 일어난다.', '아침으로 바나나와 우유를 먹는다.', '학교에 늦게 도착하는 편이다.', '일주일에 두 번 춤 수업을 듣는다.'], a: 2, why: 'she gets there early(일찍 도착한다)라고 했으므로 늦게 도착한다는 설명은 틀리다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Mr. Kim (A) [is / are] our English teacher. He (B) [come / comes] to school by bike every day, even in winter. His classes (C) [is / are] always fun because he plays English songs and games with us. Many students say English is their favorite subject now. I want to be an English teacher like him someday.</div>`, o: ['is – come – is', 'is – comes – are', 'are – comes – are', 'is – comes – is'], a: 1, why: '(A) 주어 Mr. Kim은 단수 → is. (B) He는 3인칭 단수 → comes. (C) His classes는 복수 → are.' },
    { lv: 5, q: `다음 글을 읽고 답할 수 <b>없는</b> 질문은?<div class="passage">Hana and her grandmother live in a small town. Every Saturday, they go to the market together. Her grandmother buys fresh vegetables, and Hana carries the bag. They don't buy meat because her grandmother doesn't eat it. After shopping, they have noodles at a small restaurant. The owner knows them well and always says hello.</div>`, o: ['When do they go to the market?', 'What does Hana carry?', "Why don't they buy meat?", 'How much are the noodles?'], a: 3, why: '국수의 가격은 글에 나오지 않는다. 시장에 가는 때(토요일), 하나가 드는 것(가방), 고기를 안 사는 이유(할머니가 안 드심)는 알 수 있다.' },
    { lv: 5, q: `밑줄 친 ①~④ 중 어법상 올바른 것끼리 짝지은 것은?<div class="passage">Dear Jenny,<br>I <u>①&nbsp;am</u> Minsu, and I live in Korea. I am very happy that you are my new e-mail friend. I <u>②&nbsp;has</u> a question for you. <u>③&nbsp;Do</u> you like K-pop? My friends and I <u>④&nbsp;loves</u> it a lot. We sing K-pop songs together every Friday. Please write back soon.<br>Your friend, Minsu</div>`, o: ['①, ③', '①, ②', '②, ④', '③, ④'], a: 0, why: '① I am, ③ Do you like는 맞다. ② I 뒤에는 have, ④ My friends and I는 복수라서 love를 써야 한다.' },
  ],
});

ENG.add('m1', '명사·관사·대명사', {
  sub: '복수형, a/an/the, 인칭대명사의 격',
  kw: ['셀 수 있는 명사', '복수형', '불규칙 복수', 'a/an', 'the', '인칭대명사', '소유격', '목적격'],
  sections: [
    { h: '셀 수 있는 명사와 복수형',
      p: '하나, 둘 셀 수 있는 명사는 둘 이상일 때 <span class="hl">복수형</span>으로 쓴다. 대부분 -s를 붙이지만 규칙이 다른 것과 모양이 완전히 바뀌는 것이 있다. water, milk, bread처럼 셀 수 없는 명사는 복수형을 쓰지 않고, a glass of milk처럼 그릇 단위로 센다.',
      table: { head: ['규칙', '예'], rows: [['대부분 +s', 'book → books, cat → cats'], ['-s, -sh, -ch, -x + es', 'box → boxes, dish → dishes'], ['자음 + y → ies', 'baby → babies, city → cities'], ['-f / -fe → ves', 'leaf → leaves, knife → knives, wolf → wolves'], ['불규칙', 'man → men, child → children, foot → feet, tooth → teeth, mouse → mice'], ['단수·복수 같음', 'sheep → sheep, fish → fish']], cap: '명사의 복수형 만드는 법' },
      ex: [["I have two boxes of crayons.", "나는 크레파스 두 상자가 있다."], ["The children are playing in the park.", "아이들이 공원에서 놀고 있다."], ["I drink two glasses of milk a day.", "나는 하루에 우유 두 잔을 마신다."]],
      warn: 'breads, waters, sheeps, childrens는 모두 틀린 형태이다.' },
    { h: '관사 a / an / the',
      p: '<b>a / an</b>은 셀 수 있는 명사 하나 앞에 쓰며 "하나의, 어떤"이라는 뜻이다. 철자가 아니라 <span class="hl">첫소리</span>가 모음 소리이면 an을 쓴다. <b>the</b>는 앞에서 말한 것, 서로 알고 있는 것, 세상에 하나뿐인 것(the sun, the moon), 악기 이름 앞에 쓴다.',
      table: { head: ['구분', '쓰는 경우', '예'], rows: [['a', '자음 소리로 시작', 'a book, a university, a uniform'], ['an', '모음 소리로 시작', 'an apple, an egg, an hour, an honest boy'], ['the', '앞에 나온 것 / 하나뿐인 것 / 악기', 'the sun, play the piano']] },
      ex: [["I saw a dog. The dog was very big.", "나는 개 한 마리를 보았다. 그 개는 매우 컸다."], ["She waited for an hour.", "그녀는 한 시간 동안 기다렸다."], ["He plays the violin well.", "그는 바이올린을 잘 연주한다."]],
      tip: 'hour는 h가 소리 나지 않아 [아워]로 시작하므로 an hour, university는 [유]로 시작하므로 a university이다.' },
    { h: '인칭대명사의 격',
      p: '대명사는 문장에서 하는 역할에 따라 모양이 바뀐다. 주어 자리에는 주격, "~의"는 소유격, 동사·전치사 뒤에는 목적격, "~의 것"은 소유대명사를 쓴다.',
      table: { head: ['주격(~은/는)', '소유격(~의)', '목적격(~을/에게)', '소유대명사(~의 것)'], rows: [['I', 'my', 'me', 'mine'], ['you', 'your', 'you', 'yours'], ['he', 'his', 'him', 'his'], ['she', 'her', 'her', 'hers'], ['it', 'its', 'it', '-'], ['we', 'our', 'us', 'ours'], ['they', 'their', 'them', 'theirs']], cap: '인칭대명사의 격 변화' },
      ex: [["This is my bag. That one is yours.", "이것은 내 가방이다. 저것은 너의 것이다."], ["Mr. Park is our teacher. We like him.", "박 선생님은 우리 선생님이다. 우리는 그를 좋아한다."]],
      warn: "its(그것의)와 it's(it is)를 헷갈리지 않도록 한다." },
  ],
  bank: [
    { lv: 1, q: 'child의 복수형으로 알맞은 것은?', o: ['childs', 'childes', 'children', 'childrens'], a: 2, why: 'child는 불규칙 복수형 children을 쓴다. childrens는 복수형에 -s를 또 붙인 잘못된 형태이다.' },
    { lv: 1, q: '빈칸에 a가 아니라 an이 들어가야 하는 것은?', o: ['___ book', '___ umbrella', '___ cat', '___ university'], a: 1, why: 'umbrella는 모음 소리 [ʌ]로 시작하므로 an을 쓴다. university는 [유] 소리로 시작해서 a를 쓴다.' },
    { lv: 1, q: 'she의 목적격으로 알맞은 것은?', o: ['she', 'hers', 'herself', 'her'], a: 3, why: 'she의 목적격은 her이다. hers는 소유대명사(그녀의 것)이다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>I play ___ piano once a day.', o: ['a', 'an', 'the', '×(필요 없음)'], a: 2, why: '악기 이름 앞에는 the를 쓴다. play the piano.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>I brush my ___ three times a day.', o: ['tooths', 'teeth', 'tooth', 'teeths'], a: 1, why: 'tooth의 복수형은 teeth이다. 이를 닦는 것은 여러 개의 이이므로 복수형을 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>I need some ___ to drink.', o: ['water', 'waters', 'a water', 'an water'], a: 0, why: 'water는 셀 수 없는 명사라서 a/an을 붙이거나 복수형을 만들지 않는다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I have two boxes.', 'She is an honest girl.', 'We need three knifes.', 'He bought a pair of shoes.'], a: 2, why: 'knife의 복수형은 knives이다. honest는 h가 소리 나지 않아 an honest가 맞다.' },
    { lv: 3, q: '빈칸에 들어갈 말이 순서대로 바르게 짝지어진 것은?<br>Mr. Park is ___ teacher. ___ students love ___.', o: ['our – His – him', 'we – He – his', 'us – His – he', 'our – He – him'], a: 0, why: '명사 teacher 앞은 소유격 our, students 앞도 소유격 His, 동사 love 뒤는 목적격 him이다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['Can you give me some breads?', 'There are many sheeps on the farm.', 'She wants to be a engineer.', 'I drink two glasses of milk a day.'], a: 3, why: 'milk는 glass로 센다. bread는 셀 수 없어 breads가 틀리고, sheep은 복수도 sheep, engineer 앞에는 an을 쓴다.' },
    { lv: 4, q: `빈칸 (A), (B)에 들어갈 말로 알맞은 것은?<div class="passage">My aunt has a small farm. She has three cows, ten chickens, and two sheep. Every morning, she gets eggs from the chickens. She gives some of (A) <span class="blank"></span> to us. My mom uses the eggs to make cake. My brother and I love the cake. Our aunt always says (B) <span class="blank"></span> farm is our second home.</div>`, o: ['it – her', 'them – her', 'them – hers', 'they – she'], a: 1, why: '(A)는 eggs를 가리키고 전치사 of 뒤이므로 목적격 them, (B)는 명사 farm 앞이므로 소유격 her이다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Last Sunday, my family went to the zoo. We saw many <u>①&nbsp;animals</u> there. There were two <u>②&nbsp;wolfs</u> and five <u>③&nbsp;monkeys</u>. The monkeys ate bananas, and the <u>④&nbsp;children</u> laughed at them. I took a lot of pictures with my new camera. It was a wonderful day.</div>`, o: ['①', '②', '③', '④'], a: 1, why: 'wolf는 f를 v로 고치고 -es를 붙여 wolves가 된다. monkey는 모음 + y라서 monkeys가 맞다.' },
    { lv: 4, q: `밑줄 친 부분이 가리키는 대상이 나머지 셋과 <b>다른</b> 것은?<div class="passage">Jisu has a younger brother, Minho. <u>①&nbsp;He</u> is seven years old. Jisu helps <u>②&nbsp;him</u> with his homework every day. Jisu's father works at a hospital. <u>③&nbsp;He</u> is a doctor. Minho says <u>④&nbsp;his</u> dream is to become a doctor, too.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '③ He는 지수의 아버지를 가리키고, 나머지는 모두 민호를 가리킨다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">I have (A) [a / an] uncle in Canada. He is a pilot, so he flies to many (B) [country / countries]. Last month, he sent me a gift. It was a book about (C) [the / a] moon. It has many pictures, and I read it every night. I want to fly a plane like my uncle someday.</div>`, o: ['a – countries – the', 'an – countries – the', 'an – country – a', 'an – countries – a'], a: 1, why: '(A) uncle은 모음 소리로 시작 → an. (B) many 뒤에는 복수형 countries. (C) 달은 하나뿐이므로 the moon.' },
    { lv: 5, q: `빈칸 (A)~(D) 중 an이 들어갈 곳끼리 짝지은 것은?<div class="passage">Yesterday, I read (A) <span class="blank"></span> interesting story. It was about (B) <span class="blank"></span> small boy and his dog. Every day, the boy walked with the dog for (C) <span class="blank"></span> hour. One day, the dog found (D) <span class="blank"></span> useful thing in the park: a lost wallet. The boy gave it to the police. The owner thanked them with a big smile.</div>`, o: ['(A), (B)', '(A), (C)', '(B), (D)', '(C), (D)'], a: 1, why: 'interesting과 hour는 모음 소리로 시작하므로 an을 쓴다. small은 자음, useful은 [유] 소리로 시작하므로 a를 쓴다.' },
    { lv: 5, q: `밑줄 친 <u>They</u>가 가리키는 것은?<div class="passage">In our classroom, there are twenty desks and a big window. On the wall, there are some posters. <u>They</u> show famous scientists like Marie Curie and Jang Yeong-sil. Our teacher put them there to give us big dreams. Next to the window, there is a small plant. We water it every Monday.</div>`, o: ['desks', 'scientists', 'windows', 'posters'], a: 3, why: '과학자들을 "보여 주는" 것은 벽에 붙은 포스터(posters)이다. scientists는 포스터에 나오는 대상이다.' },
  ],
});

ENG.add('m1', '현재진행형과 미래 표현', {
  sub: '지금 하는 일과 앞으로 할 일 말하기',
  kw: ['현재진행형', 'be + -ing', '-ing 만드는 법', 'will', 'be going to', '미래 표현', '진행형을 쓰지 않는 동사'],
  sections: [
    { h: '현재진행형: be동사 + -ing',
      p: '현재진행형은 "지금 ~하고 있다"라는 뜻으로, <span class="hl">am/are/is + 동사-ing</span>로 만든다. now, right now, Look!, Listen! 같은 말과 자주 함께 쓴다.',
      table: { head: ['동사 끝', '-ing 만드는 법', '예'], rows: [['대부분', '+ing', 'read → reading, play → playing'], ['-e로 끝남', 'e를 빼고 +ing', 'make → making, come → coming'], ['-ie로 끝남', 'ie를 y로 고치고 +ing', 'lie → lying, die → dying'], ['단모음 + 단자음', '자음을 한 번 더 쓰고 +ing', 'run → running, swim → swimming, sit → sitting']], cap: '동사의 -ing형 만드는 법' },
      ex: [["Look! The baby is sleeping.", "봐! 아기가 자고 있어."], ["We are having lunch now.", "우리는 지금 점심을 먹고 있다."], ["My dad is washing the car.", "아빠는 세차를 하고 계신다."]] },
    { h: '진행형의 부정문·의문문',
      p: '부정문은 be동사 뒤에 not을 붙이고, 의문문은 be동사를 주어 앞으로 보낸다. 대답도 be동사로 한다. 한편 <b>know, like, want, have(가지고 있다)</b>처럼 상태나 마음을 나타내는 동사는 보통 진행형으로 쓰지 않는다.',
      ex: [["He is not watching TV now.", "그는 지금 TV를 보고 있지 않다."], ["Are you listening to me? — Yes, I am.", "내 말 듣고 있니? — 응, 듣고 있어."], ["I know the answer.", "나는 정답을 안다."]],
      warn: 'I am knowing the answer. (×) → I know the answer. (○)' },
    { h: '미래 표현: will과 be going to',
      p: '앞으로의 일은 <span class="hl">will + 동사원형</span> 또는 <span class="hl">be going to + 동사원형</span>으로 나타낸다. will은 말하는 순간 정한 일이나 예측에, be going to는 미리 계획한 일에 자주 쓴다.',
      table: { head: ['구분', '긍정', '부정', '의문'], rows: [['will', 'I will help you.', "I will not(won't) help you.", 'Will you help me?'], ['be going to', 'She is going to visit Jeju.', "She isn't going to visit Jeju.", 'Is she going to visit Jeju?']] },
      ex: [["It will rain tomorrow.", "내일 비가 올 것이다."], ["We are going to have a party this Friday.", "우리는 이번 금요일에 파티를 할 예정이다."]],
      warn: 'will 뒤와 be going to 뒤는 모두 동사원형이다. will goes (×), is going to visits (×)' },
  ],
  bank: [
    { lv: 1, q: 'swim의 -ing형으로 알맞은 것은?', o: ['swiming', 'swimming', 'swimeing', 'swimmming'], a: 1, why: 'swim은 단모음 + 단자음으로 끝나므로 m을 한 번 더 쓰고 -ing를 붙인다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>Look! The baby ___.', o: ['sleep', 'sleeps', 'is sleeping', 'are sleeping'], a: 2, why: 'Look!은 지금 일어나는 일을 가리키므로 현재진행형을 쓰고, 주어 The baby가 단수라서 is sleeping이다.' },
    { lv: 1, q: 'will 바로 뒤에 오는 동사의 형태는?', o: ['동사원형', '-ing형', '과거형', 'to + 동사원형'], a: 0, why: '조동사 will 뒤에는 항상 동사원형을 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>They ___ going to visit Jeju next week.', o: ['is', 'am', 'are', 'do'], a: 2, why: '주어 They가 복수이므로 are going to를 쓴다.' },
    { lv: 2, q: '대답의 빈칸에 알맞은 말은?<br>Will you come to my party? — Yes, ___.', o: ['I do', 'I will', 'I am', 'I come'], a: 1, why: 'Will로 물으면 will로 답한다. Yes, I will. / No, I won\'t.' },
    { lv: 2, q: '우리말과 뜻이 같은 문장은?<br>그는 지금 TV를 보고 있지 않다.', o: ["He doesn't watching TV now.", 'He not is watching TV now.', 'He is watching not TV now.', 'He is not watching TV now.'], a: 3, why: '진행형의 부정은 be동사 뒤에 not을 붙인다. does와 -ing를 함께 쓰지 않는다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I am knowing the answer.', 'She is making a cake.', 'We are going to play tennis.', 'It will rain tomorrow.'], a: 0, why: 'know는 상태를 나타내는 동사라서 진행형으로 쓰지 않는다. I know the answer.가 맞다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['He will goes to the library.', 'Are you going to buy a new phone?', 'She is going to visits her aunt.', 'I am have lunch now.'], a: 1, why: 'be going to의 의문문은 be동사를 앞으로 보낸다. will과 be going to 뒤에는 동사원형, 진행형은 be + -ing이다.' },
    { lv: 3, q: '상황: 미나는 지금 책을 읽는 것이 아니라 편지를 쓰고 있다. 질문에 대한 대답으로 알맞은 것은?<br>Is Mina reading a book?', o: ['Yes, she is. She is writing a letter.', "No, she doesn't. She writes a letter.", "No, she isn't. She is writing a letter.", "No, she isn't. She is write a letter."], a: 2, why: '책을 읽고 있지 않으므로 No, she isn\'t.로 답하고, 지금 하는 일은 현재진행형 is writing으로 말한다.' },
    { lv: 4, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Tomorrow is Saturday. My class is going to have a picnic at Green Park. We are going to leave school at nine. Our teacher will bring a big ball, and we will play games. I am going to make some sandwiches tonight. My friend Dami is going to bring fruit. I hope it will be sunny.</div>`, o: ['소풍은 일요일에 간다.', '학생들은 9시에 학교를 출발한다.', '선생님이 샌드위치를 가져온다.', '다미는 공을 가져온다.'], a: 1, why: 'We are going to leave school at nine.이라고 했다. 소풍은 토요일, 샌드위치는 글쓴이, 공은 선생님, 다미는 과일을 가져온다.' },
    { lv: 4, q: `빈칸 (A), (B)에 들어갈 말로 알맞은 것은?<div class="passage">Mom: Hello, Jun. Where are you?<br>Jun: I'm at the library, Mom.<br>Mom: What are you doing there?<br>Jun: I'm (A) <span class="blank"></span> for my science test with Tom.<br>Mom: OK. Dinner is at seven. Don't be late.<br>Jun: Don't worry. I (B) <span class="blank"></span> be home by six thirty.</div>`, o: ['study – am', 'studying – will', 'studying – am going', 'studied – will'], a: 1, why: '(A) I\'m 뒤 지금 하는 일이므로 studying. (B) 뒤에 동사원형 be가 오므로 will이 알맞다. am going 뒤에는 to가 필요하다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">It is Sunday afternoon. My family is in the living room. My dad <u>①&nbsp;is reading</u> a newspaper. My mom <u>②&nbsp;is talking</u> on the phone with my aunt. My little brother <u>③&nbsp;is lieing</u> on the sofa. I <u>④&nbsp;am writing</u> in my diary. We are all relaxing at home.</div>`, o: ['①', '②', '③', '④'], a: 2, why: 'lie는 ie를 y로 고쳐 lying이 된다. write는 e를 빼고 writing이 되므로 ④는 맞다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Next month, my grandparents (A) [will visit / visited] us from Jeonju. They (B) [are / is] going to stay for a week. My mom (C) [is cleaning / cleans] the guest room right now. My sister and I are making a welcome card for them. We can't wait to see them!</div>`, o: ['will visit – are – is cleaning', 'visited – are – is cleaning', 'will visit – is – cleans', 'will visit – are – cleans'], a: 0, why: '(A) Next month는 미래 → will visit. (B) They는 복수 → are. (C) right now는 지금 진행 중 → is cleaning.' },
    { lv: 5, q: `다음 글을 쓴 수진이가 지금 하고 있는 일은?<div class="passage">Dear Grandma,<br>How are you? I'm writing this letter on the train. Right now, the train is passing a big river, and many birds are flying over it. I'm going to arrive in Seoul at three. Uncle Min will meet me at the station. Tomorrow we are going to visit a science museum. I'll call you tonight.<br>Love, Sujin</div>`, o: ['역에서 삼촌을 기다리고 있다', '과학관을 구경하고 있다', '기차에서 편지를 쓰고 있다', '할머니께 전화하고 있다'], a: 2, why: 'I\'m writing this letter on the train.이 지금 하는 일이다. 삼촌을 만나는 것, 과학관 방문, 전화는 앞으로 할 일이다.' },
    { lv: 5, q: `다음 글을 읽고 답할 수 <b>없는</b> 질문은?<div class="passage">This summer vacation, Kevin is going to learn swimming. He can't swim now, so he is a little worried. His swimming class will start on July 20. It's at the sports center near his house. His older sister is a good swimmer. She is going to help him practice on weekends.</div>`, o: ['What is Kevin going to learn?', 'When will the class start?', 'Who will help Kevin?', 'How much is the swimming class?'], a: 3, why: '수업료는 글에 나오지 않는다. 배울 것(수영), 시작일(7월 20일), 도와줄 사람(누나)은 알 수 있다.' },
  ],
});

ENG.add('m1', '과거 시제', {
  sub: 'was/were와 동사의 과거형으로 지난 일 말하기',
  kw: ['과거 시제', 'was/were', '-ed', '불규칙 동사', "didn't", 'Did ~?', 'yesterday', 'ago'],
  sections: [
    { h: 'be동사의 과거형',
      p: 'be동사의 과거형은 <span class="hl">was</span>와 <span class="hl">were</span> 두 가지이다. I와 3인칭 단수에는 was, you와 복수에는 were를 쓴다. 부정은 wasn\'t / weren\'t, 의문은 Was / Were를 주어 앞에 둔다.',
      table: { head: ['주어', '현재', '과거'], rows: [['I', 'am', 'was'], ['he / she / it / 단수', 'is', 'was'], ['you / we / they / 복수', 'are', 'were']] },
      ex: [["I was sick yesterday.", "나는 어제 아팠다."], ["Were they at the concert? — Yes, they were.", "그들은 콘서트에 있었니? — 응, 있었어."]] },
    { h: '일반동사의 과거형',
      p: '일반동사는 대부분 <span class="hl">-ed</span>를 붙여 과거형을 만든다. 과거형은 주어가 무엇이든 모양이 같다. 그러나 go → went처럼 모양이 불규칙하게 바뀌는 동사가 많으므로 따로 외워야 한다.',
      table: { head: ['규칙 / 불규칙', '만드는 법 / 형태', '예'], rows: [['대부분', '+ed', 'play → played, visit → visited'], ['-e로 끝남', '+d', 'like → liked, arrive → arrived'], ['자음 + y', 'y → ied', 'study → studied, cry → cried'], ['단모음 + 단자음', '자음 한 번 더 + ed', 'stop → stopped, plan → planned'], ['불규칙(모양 변화)', '따로 외움', 'go → went, eat → ate, see → saw, buy → bought, make → made'], ['불규칙(모양 같음)', '현재형과 같음', 'put → put, read → read, cut → cut']], cap: '동사의 과거형 만드는 법' },
      ex: [["We visited the museum last week.", "우리는 지난주에 박물관을 방문했다."], ["She went to bed early.", "그녀는 일찍 잠자리에 들었다."]],
      tip: 'read의 과거형은 철자는 같지만 [레드]로 읽는다.' },
    { h: '과거의 부정문·의문문과 시간 표현',
      p: '일반동사 과거 문장의 부정은 <span class="hl">didn\'t + 동사원형</span>, 의문은 <span class="hl">Did + 주어 + 동사원형 ~?</span>이다. did가 이미 과거를 나타내므로 뒤의 동사는 원형으로 쓴다. yesterday, last ~, ~ ago, in 2020 같은 말이 있으면 과거 시제를 쓴다.',
      ex: [["I didn't watch TV last night.", "나는 어젯밤에 TV를 보지 않았다."], ["Did you finish your homework? — No, I didn't.", "숙제 끝냈니? — 아니, 못 했어."], ["He moved to Seoul two years ago.", "그는 2년 전에 서울로 이사했다."]],
      warn: "She didn't went (×) → She didn't go (○). Did she bought (×) → Did she buy (○)" },
  ],
  bank: [
    { lv: 1, q: 'go의 과거형으로 알맞은 것은?', o: ['goed', 'went', 'gone', 'going'], a: 1, why: 'go는 불규칙 동사로 과거형은 went이다. gone은 과거분사이다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I ___ at home yesterday.', o: ['were', 'am', 'is', 'was'], a: 3, why: 'yesterday가 있으므로 과거, 주어가 I이므로 was를 쓴다.' },
    { lv: 1, q: 'stop의 과거형으로 알맞은 것은?', o: ['stoped', 'stopping', 'stopped', 'stopt'], a: 2, why: 'stop은 단모음 + 단자음으로 끝나므로 p를 한 번 더 쓰고 -ed를 붙인다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>They ___ not at school last Friday.', o: ['were', 'was', 'did', 'are'], a: 0, why: 'last Friday가 있어 과거이고 주어 They가 복수이므로 were를 쓴다. 장소에 있었다는 뜻이므로 be동사가 필요하다.' },
    { lv: 2, q: '대답의 빈칸에 알맞은 말은?<br>Did you finish your homework? — No, I ___.', o: ["don't", "wasn't", "didn't", "weren't"], a: 2, why: 'Did로 물으면 did / didn\'t로 답한다.' },
    { lv: 2, q: '우리말과 뜻이 같은 문장은?<br>그녀는 어제 영화를 보지 않았다.', o: ["She didn't watched a movie yesterday.", "She didn't watch a movie yesterday.", "She doesn't watch a movie yesterday.", "She wasn't watch a movie yesterday."], a: 1, why: '과거 부정은 didn\'t + 동사원형이다. didn\'t 뒤에 watched를 쓰면 과거 표시가 두 번이 된다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I met him two days ago.', 'We were very tired last night.', 'He studied hard for the test.', 'Did she buys a new bag?'], a: 3, why: 'Did 의문문에서는 동사원형을 쓴다. Did she buy a new bag?이 맞다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['He readed the book last week.', 'I visit my uncle last Sunday.', 'Were you sick yesterday?', 'She cryed all night.'], a: 2, why: 'you의 be동사 과거형은 were이다. read의 과거형은 read, last Sunday면 visited, cry는 cried이다.' },
    { lv: 3, q: '두 문장의 빈칸에 공통으로 알맞은 말은?<br>• ___ you happy yesterday?<br>• We ___ in the same class last year.', o: ['Was', 'Were', 'Did', 'Are'], a: 1, why: '둘 다 과거이고 주어가 you, we이므로 were를 쓴다. 형용사 happy와 장소 표현 앞이라 Did는 쓸 수 없다.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Yesterday was my birthday. In the morning, my mom made seaweed soup for me. At school, my friends sang a birthday song. After school, I went to a pizza restaurant with my family. My dad gave me a new watch. I didn't expect it, so I was very surprised. It was the best birthday ever.</div>`, o: ['엄마가 미역국을 끓여 주셨다.', '친구들이 생일 노래를 불러 주었다.', '가족과 피자 가게에 갔다.', '아빠의 선물을 미리 알고 있었다.'], a: 3, why: 'I didn\'t expect it, so I was very surprised.라고 했으므로 선물을 미리 알지 못했다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Last weekend, I <u>①&nbsp;goed</u> camping with my family. We <u>②&nbsp;arrived</u> at the campsite at noon. My dad <u>③&nbsp;put</u> up the tent, and my sister and I <u>④&nbsp;cooked</u> ramyeon. At night, we looked at the stars. There were so many! I want to go camping again.</div>`, o: ['①', '②', '③', '④'], a: 0, why: 'go의 과거형은 went이다. put은 과거형이 현재형과 같아서 ③은 맞다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">A: What did you do last Saturday?<br>B: I (A) <span class="blank"></span> my grandparents in Suwon.<br>A: Did you have a good time?<br>B: Yes, I (B) <span class="blank"></span>. We (C) <span class="blank"></span> to a famous fortress together.<br>A: Sounds great. What did you do there?<br>B: We walked along the wall and took many pictures.</div>`, o: ['visit – did – go', 'visited – did – went', 'visited – was – went', 'visited – did – goed'], a: 1, why: '(A) 지난 토요일 일이므로 visited. (B) Did로 물었으므로 did. (C) go의 과거형 went.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">When I was nine, I (A) [lose / lost] my favorite cap at the park. I (B) [cried / cryed] a lot that night. The next day, my neighbor, Mr. Lee, (C) [bring / brought] it to our house. He found it on a bench. I still wear that cap, and I always say hello to Mr. Lee.</div>`, o: ['lose – cried – brought', 'lost – cried – brought', 'lost – cryed – brought', 'lost – cried – bring'], a: 1, why: '모두 과거의 일이다. lose → lost, cry → cried(자음 + y), bring → brought.' },
    { lv: 5, q: `호준이가 한 일을 순서대로 바르게 나열한 것은?<div class="passage">Last Sunday, Hojun woke up late. He ate breakfast quickly and ran to the bus stop. But he missed the bus, so he walked to the library. At the library, he met his friend Yerin. They studied together for two hours. Then they had lunch at a small cafe.</div>`, o: ['늦게 일어남 → 예린을 만남 → 버스를 놓침 → 점심을 먹음', '버스를 놓침 → 늦게 일어남 → 점심을 먹음 → 예린을 만남', '늦게 일어남 → 버스를 놓침 → 예린을 만남 → 점심을 먹음', '늦게 일어남 → 버스를 놓침 → 점심을 먹음 → 예린을 만남'], a: 2, why: 'woke up late → missed the bus → met Yerin → studied → had lunch 순서이다.' },
    { lv: 5, q: `밑줄 친 <u>readed</u>를 바르게 고친 것은?<div class="passage">Two years ago, my family moved to a new city. At first, I didn't have any friends there. I felt lonely. Then one day, a girl in my class asked me, "Do you want to join our book club?" I said yes. We <u>readed</u> many books together and talked about them. Now she is my best friend.</div>`, o: ['reading', 'reads', 'read', 'was read'], a: 2, why: '지난 일을 말하고 있으므로 과거형이 필요하다. read의 과거형은 철자가 같은 read이다.' },
  ],
});

ENG.add('m1', '조동사 can·will·must', {
  sub: '능력·허락·의무를 나타내는 조동사',
  kw: ['조동사', 'can', 'be able to', 'will', 'must', 'have to', 'must not', "don't have to"],
  sections: [
    { h: '조동사의 기본 규칙과 can',
      p: '조동사는 동사 앞에서 뜻을 더해 주는 말이다. 조동사 뒤에는 항상 <span class="hl">동사원형</span>을 쓰고, 주어가 3인칭 단수여도 조동사에 -s를 붙이지 않는다. can은 "~할 수 있다(능력)", "~해도 된다(허락)"라는 뜻이며, 능력의 can은 be able to로 바꿔 쓸 수 있다.',
      table: { head: ['조동사', '뜻', '예문'], rows: [['can', '~할 수 있다(능력)', 'She can swim well.'], ['can', '~해도 된다(허락)', 'You can use my pen.'], ['will', '~할 것이다(미래·의지)', 'I will call you later.'], ['must', '~해야 한다(의무)', 'You must wear a seat belt.'], ['must', '~임에 틀림없다(강한 추측)', 'He must be tired.']], cap: '조동사의 주요 뜻' },
      ex: [["He can play the guitar.", "그는 기타를 칠 수 있다."], ["He is able to play the guitar.", "그는 기타를 칠 수 있다."], ["Can I open the window?", "창문을 열어도 될까요?"]],
      warn: 'She cans (×), She can plays (×) → She can play (○)' },
    { h: 'will과 부탁하기',
      p: 'will은 미래의 일이나 말하는 사람의 의지를 나타낸다. 부정형은 will not, 줄여서 <span class="hl">won\'t</span>이다. <b>Will you ~?</b>는 "~해 줄래?"라는 부탁으로도 자주 쓴다. 조동사는 두 개를 겹쳐 쓸 수 없으므로 "~할 수 있을 것이다"는 will be able to로 쓴다.',
      ex: [["I won't be late again.", "다시는 늦지 않을게."], ["Will you help me with this box?", "이 상자 좀 도와줄래?"], ["You will be able to speak English well.", "너는 영어를 잘 말할 수 있게 될 것이다."]],
      warn: 'will can (×) → will be able to (○)' },
    { h: 'must, have to, must not, don\'t have to',
      p: 'must와 have to는 모두 "~해야 한다"는 의무를 나타낸다. 주어가 3인칭 단수이면 has to를 쓴다. 부정형은 뜻이 완전히 다르다. <span class="hl">must not</span>은 "~하면 안 된다(금지)", <span class="hl">don\'t have to</span>는 "~할 필요가 없다(불필요)"이다.',
      table: { head: ['표현', '뜻', '예문'], rows: [['must / have to', '~해야 한다', 'We have to wait here.'], ['must not', '~하면 안 된다(금지)', 'You must not run in the hallway.'], ["don't have to", '~할 필요가 없다', "You don't have to bring lunch."]], cap: '의무·금지·불필요 표현 비교' },
      ex: [["She has to finish the report today.", "그녀는 오늘 보고서를 끝내야 한다."], ["You must not touch the paintings.", "그림을 만지면 안 된다."], ["Tomorrow is Sunday. You don't have to get up early.", "내일은 일요일이다. 일찍 일어날 필요가 없다."]] },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>She can ___ the guitar.', o: ['plays', 'play', 'playing', 'to play'], a: 1, why: '조동사 can 뒤에는 동사원형을 쓴다.' },
    { lv: 1, q: 'must not의 뜻으로 알맞은 것은?', o: ['~해야 한다', '~할 필요가 없다', '~할 수 있다', '~하면 안 된다'], a: 3, why: 'must not은 금지를 나타낸다. "~할 필요가 없다"는 don\'t have to이다.' },
    { lv: 1, q: 'will not을 줄인 말로 알맞은 것은?', o: ["won't", "willn't", "wont'", "wo'nt"], a: 0, why: 'will not의 줄임말은 won\'t이다.' },
    { lv: 2, q: '두 문장의 뜻이 같도록 빈칸에 알맞은 말은?<br>He can speak Chinese. = He ___ speak Chinese.', o: ['are able to', 'able to', 'is able to', 'is able'], a: 2, why: '능력의 can은 be able to로 바꿀 수 있고, 주어 He에 맞춰 is able to를 쓴다.' },
    { lv: 2, q: '<b>Can I use your pen?</b>의 can과 뜻이 같은 것은?', o: ['I can ride a bike.', 'Can you swim?', 'You can go home now.', "She can't speak Japanese."], a: 2, why: '주어진 문장의 can은 허락(~해도 된다)이다. You can go home now.도 허락이고, 나머지는 능력이다.' },
    { lv: 2, q: '우리말에 맞게 빈칸에 알맞은 말은?<br>내일은 일요일이다. 너는 일찍 일어날 필요가 없다.<br>You ___ get up early.', o: ['must not', "don't have to", "can't", "won't"], a: 1, why: '"~할 필요가 없다"는 don\'t have to이다. must not은 "~하면 안 된다"라는 금지이다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['You must wear a helmet.', 'Will you open the window?', 'She cans dance well.', 'We have to wait here.'], a: 2, why: '조동사에는 -s를 붙이지 않는다. She can dance well.이 맞다.' },
    { lv: 3, q: '밑줄 친 must의 뜻이 나머지 셋과 <b>다른</b> 것은?', o: ['He <u>must</u> be very tired.', 'You <u>must</u> be quiet in the library.', 'We <u>must</u> follow the rules.', 'Students <u>must</u> wear uniforms.'], a: 0, why: '①은 "피곤함에 틀림없다"라는 강한 추측이고, 나머지는 "~해야 한다"라는 의무이다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['He has to finishes it today.', 'Can she swims?', 'I will can help you.', "She doesn't have to cook tonight."], a: 3, why: 'doesn\'t have to + 동사원형이 맞다. has to와 can 뒤에는 원형, 조동사 두 개(will can)는 겹쳐 쓸 수 없다.' },
    { lv: 4, q: `다음 안내문의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Welcome to Sunny Library! Please follow these rules. You can borrow up to five books at a time. You must return them in two weeks. You must not eat or drink inside. You can use the computers for one hour. You don't have to pay for anything. Thank you!</div>`, o: ['한 번에 다섯 권까지 빌릴 수 있다.', '책은 2주 안에 반납해야 한다.', '도서관 안에서 음료를 마실 수 있다.', '이용료를 낼 필요가 없다.'], a: 2, why: 'You must not eat or drink inside.라고 했으므로 안에서 마시면 안 된다.' },
    { lv: 4, q: `빈칸 (A), (B)에 들어갈 말로 알맞은 것은?<div class="passage">Dad: Minji, it's already ten o'clock. You (A) <span class="blank"></span> go to bed now.<br>Minji: But Dad, I have a math test tomorrow. (B) <span class="blank"></span> I study for one more hour?<br>Dad: Hmm... OK, but you must not use your phone.<br>Minji: Thanks, Dad. I promise.</div>`, o: ['must – Can', 'can – Must', 'must – Will', "don't have to – Can"], a: 0, why: '(A) 잘 시간이니 "자야 한다" → must. (B) 한 시간 더 공부해도 되는지 허락을 구하므로 Can.' },
    { lv: 4, q: `다음 글에서 Jake가 할 수 <b>없는</b> 것은?<div class="passage">Jake is my classmate from Canada. He came to Korea last year. Now he can speak Korean very well. He can also cook some Korean food, like bibimbap. But he can't eat spicy food. Next week, he will go back to Canada for the holidays. He will visit his grandparents there.</div>`, o: ['한국어 말하기', '매운 음식 먹기', '비빔밥 만들기', '캐나다 방문하기'], a: 1, why: 'But he can\'t eat spicy food.라고 했다.' },
    { lv: 5, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Our school will <u>①&nbsp;have</u> a sports day next Friday. All students must <u>②&nbsp;wear</u> sneakers. You can <u>③&nbsp;to bring</u> your own water bottle. You don't have to <u>④&nbsp;bring</u> lunch because the school will give you sandwiches. It will be a fun day!</div>`, o: ['①', '②', '③', '④'], a: 2, why: '조동사 can 뒤에는 동사원형이 온다. to bring이 아니라 bring이다. ④는 have to 뒤라서 원형이 맞다.' },
    { lv: 5, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">The museum is free for students, so you (A) <span class="blank"></span> buy a ticket. But please remember one thing. You (B) <span class="blank"></span> touch the paintings. They are very old and can break easily. You (C) <span class="blank"></span> take pictures, but please don't use a flash.</div>`, o: ["must not – don't have to – can", "don't have to – must not – can", "don't have to – can – must not", 'must – must not – can'], a: 1, why: '(A) 무료이니 표를 살 필요 없음 → don\'t have to. (B) 오래된 그림이라 만지면 안 됨 → must not. (C) 사진은 찍어도 됨 → can.' },
    { lv: 5, q: `다음 글의 목적으로 가장 알맞은 것은?<div class="passage">Hi, Sora. This is Ms. Han. Our class will have a bake sale on Friday. Will you help us? We need students who can bake cookies. If you can't bake, that's OK. You can sell the cookies at the table. Please tell me by Wednesday. Thank you.</div>`, o: ['쿠키 만드는 법을 알려 주려고', '수요일 수업을 취소하려고', '쿠키 가격을 알려 주려고', '바자회 준비에 도움을 요청하려고'], a: 3, why: 'Will you help us?로 도움을 부탁하고, 쿠키를 굽거나 팔아 줄 것을 요청하는 글이다.' },
  ],
});

ENG.add('m1', '의문사 의문문', {
  sub: '누가·언제·어디서·왜·어떻게를 묻는 문장',
  kw: ['의문사', 'who', 'what', 'when', 'where', 'why', 'how', 'How many / How much'],
  sections: [
    { h: '의문사의 종류',
      p: '의문사는 Yes / No가 아니라 구체적인 정보를 물을 때 쓰는 말이다. 의문사는 문장 맨 앞에 오며, 대답은 Yes / No로 하지 않는다.',
      table: { head: ['의문사', '묻는 것', '예문'], rows: [['who', '사람(누구)', 'Who is that boy?'], ['what', '사물·일(무엇)', 'What is your hobby?'], ['when', '때(언제)', 'When is your birthday?'], ['where', '장소(어디)', 'Where do you live?'], ['why', '이유(왜)', 'Why are you late?'], ['how', '방법·상태(어떻게)', 'How do you go to school?'], ['which', '선택(어느 것)', 'Which do you like better, tea or coffee?'], ['whose', '소유(누구의)', 'Whose bag is this?']], cap: '의문사 정리' },
      ex: [["Where is the bus stop? — It's next to the bank.", "버스 정류장은 어디에 있니? — 은행 옆에 있어."], ["Why are you sad? — Because I lost my cap.", "왜 슬프니? — 모자를 잃어버렸거든."]] },
    { h: '의문사 의문문의 어순',
      p: '의문사 의문문은 <span class="hl">의문사 + be동사 + 주어 ~?</span>, <span class="hl">의문사 + do/does/did + 주어 + 동사원형 ~?</span>, <span class="hl">의문사 + 조동사 + 주어 + 동사원형 ~?</span>의 순서로 쓴다. 단, 의문사가 주어일 때는 바로 동사가 온다.',
      ex: [["What does she like?", "그녀는 무엇을 좋아하니?"], ["Where did you buy it?", "그것을 어디에서 샀니?"], ["Who made this cake? — My sister did.", "누가 이 케이크를 만들었니? — 우리 언니가 만들었어."]],
      warn: 'Where you live? (×) → Where do you live? (○)' },
    { h: 'How + 형용사/부사, What + 명사',
      p: 'how 뒤에 형용사나 부사를 붙이면 나이, 키, 개수, 양, 횟수 등을 물을 수 있다. what time(몇 시), what kind of(어떤 종류의)처럼 what 뒤에 명사를 붙이기도 한다.',
      table: { head: ['표현', '묻는 것', '예문'], rows: [['How old', '나이', 'How old is your sister?'], ['How tall', '키·높이', 'How tall are you?'], ['How many + 복수 명사', '개수', 'How many books do you have?'], ['How much', '양·가격', 'How much is this cap?'], ['How long', '기간·길이', 'How long does it take?'], ['How often', '횟수(빈도)', 'How often do you exercise?'], ['What time', '시각', 'What time do you get up?']] },
      ex: [["How often do you play tennis? — Twice a week.", "테니스를 얼마나 자주 치니? — 일주일에 두 번."]],
      tip: 'How many 뒤에는 셀 수 있는 명사의 복수형, How much 뒤에는 셀 수 없는 명사가 온다.' },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 의문사는?<br>___ is your birthday? — It\'s May 5.', o: ['Where', 'When', 'Who', 'Why'], a: 1, why: '날짜(때)를 물으므로 When을 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 의문사는?<br>___ is that girl? — She is my cousin.', o: ['Who', 'What', 'Whose', 'Which'], a: 0, why: '사람이 누구인지 물으므로 Who를 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 의문사는?<br>___ do you go to school? — By bus.', o: ['What', 'Where', 'How', 'Why'], a: 2, why: '교통수단(방법)을 물으므로 How를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 의문사는?<br>___ are you late? — Because I missed the bus.', o: ['How', 'When', 'What', 'Why'], a: 3, why: 'Because로 이유를 답하므로 Why로 물어야 한다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>___ brothers do you have? — I have two.', o: ['How much', 'How many', 'How old', 'How long'], a: 1, why: '셀 수 있는 명사(brothers)의 개수를 물으므로 How many를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>___ bag is this? — It\'s Minsu\'s.', o: ['Who', "Who's", 'Whose', 'Which'], a: 2, why: '"누구의 가방"인지 소유를 물으므로 Whose를 쓴다. Who\'s는 Who is의 줄임말이다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['Where you live?', 'What does she likes?', 'Who did made this cake?', 'What time does the movie start?'], a: 3, why: '의문사 + does + 주어 + 동사원형 순서가 맞다. Where do you live?, What does she like?, Who made this cake?로 고쳐야 한다.' },
    { lv: 3, q: '대화가 <b>어색한</b> 것은?', o: ['A: How often do you exercise? B: Three times a week.', 'A: How old is your sister? B: She is ten.', 'A: Where did you buy it? B: Yesterday.', 'A: What kind of music do you like? B: I like jazz.'], a: 2, why: 'Where는 장소를 묻는데 Yesterday(때)로 답했으므로 어색하다.' },
    { lv: 3, q: '빈칸에 알맞은 의문사는?<br>___ do you like better, apples or bananas?', o: ['Who', 'How', 'Which', 'Where'], a: 2, why: '정해진 것 중 하나를 고르게 할 때는 Which를 쓴다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Reporter: (A) <span class="blank"></span> do you practice every day?<br>Yuna: About four hours.<br>Reporter: Wow! (B) <span class="blank"></span> did you start skating?<br>Yuna: When I was six. My mom took me to the ice rink.<br>Reporter: (C) <span class="blank"></span> is your dream?<br>Yuna: I want to win a gold medal at the Olympics.</div>`, o: ['How long – When – What', 'How many – When – What', 'How long – Where – Why', 'How often – When – What'], a: 0, why: '(A) 네 시간이라는 기간 → How long. (B) 여섯 살 때라는 시기 → When. (C) 꿈이 무엇인지 → What.' },
    { lv: 4, q: `다음 안내문을 읽고 답할 수 <b>없는</b> 질문은?<div class="passage">Spring Concert!<br>Date: Friday, April 12<br>Time: 6:00 p.m.<br>Place: School Hall<br>The school band and choir will perform. Tickets are free, but you need to get one from the music room by April 10. Families are welcome too.</div>`, o: ['When is the concert?', 'How long will the concert be?', 'Where is the concert?', 'Who will perform?'], a: 1, why: '공연 시작 시각은 있지만 공연이 얼마나 오래 하는지는 나오지 않는다.' },
    { lv: 4, q: `글의 내용에 맞는 질문과 대답이 <b>아닌</b> 것은?<div class="passage">Mina's family has a pet rabbit. Its name is Toto. Toto is two years old. It is white with black ears. Mina's father bought it at a pet shop near their house. Toto likes carrots and apples. Mina gives it food twice a day.</div>`, o: ['How old is Toto? – It is two years old.', "Who bought Toto? – Mina's father did.", 'How often does Mina feed Toto? – Three times a day.', 'What does Toto like? – It likes carrots and apples.'], a: 2, why: 'Mina gives it food twice a day.라고 했으므로 하루에 세 번이 아니라 두 번이다.' },
    { lv: 5, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Hi, I'm Jinho. Welcome to our school! I want to know more about you. (A) <span class="blank"></span> are you from? (B) <span class="blank"></span> do you like to do in your free time? Also, (C) <span class="blank"></span> sport do you like better, soccer or basketball? Our class has a soccer team. Maybe you can join us!</div>`, o: ['Where – How – Which', 'When – What – Who', 'Where – What – Which', 'Where – What – Whose'], a: 2, why: '(A) 출신 장소 → Where. (B) 여가에 하는 일 → What. (C) 둘 중 어느 운동 → Which.' },
    { lv: 5, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">A: <u>①&nbsp;What did you do</u> last weekend?<br>B: I went to the beach.<br>A: <u>②&nbsp;Who did you go</u> with?<br>B: With my cousins.<br>A: <u>③&nbsp;How was</u> the weather?<br>B: It was perfect.<br>A: <u>④&nbsp;What time you did come</u> back home?<br>B: Around eight.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '의문사 + did + 주어 + 동사원형 순서이므로 What time did you come back home?이 맞다.' },
    { lv: 5, q: `대화의 빈칸에 들어갈 말로 가장 알맞은 것은?<div class="passage">A: You look sad. <span class="blank"></span><br>B: I lost my bike.<br>A: Oh no. Where did you leave it?<br>B: In front of the library. I think I didn't lock it.<br>A: Let's go and look for it together.</div>`, o: ['How old are you?', "What's wrong?", 'Whose bike is it?', 'When is your birthday?'], a: 1, why: '슬퍼 보이는 친구에게 무슨 일인지 묻는 What\'s wrong?이 알맞다. B가 자전거를 잃어버린 이유를 답한다.' },
  ],
});

ENG.add('m1', '형용사·부사와 비교 기초', {
  sub: '꾸며 주는 말과 둘 이상 비교하기',
  kw: ['형용사', '부사', '-ly', '빈도부사', 'as ~ as', '비교급', '최상급', 'than'],
  sections: [
    { h: '형용사와 부사',
      p: '<b>형용사</b>는 명사를 꾸미거나(a tall boy) be동사 뒤에서 주어를 설명한다(He is tall). <b>부사</b>는 동사, 형용사, 다른 부사를 꾸민다(He runs fast). 부사는 보통 형용사 뒤에 <span class="hl">-ly</span>를 붙여 만든다.',
      table: { head: ['형용사', '부사', '규칙'], rows: [['quick, slow, careful', 'quickly, slowly, carefully', '+ly'], ['easy, happy', 'easily, happily', 'y → ily'], ['gentle, simple', 'gently, simply', 'le → ly'], ['fast, hard, early, late', 'fast, hard, early, late', '형용사와 모양 같음'], ['good', 'well', '불규칙']], cap: '형용사 → 부사 만들기' },
      ex: [["She is a careful driver. She drives carefully.", "그녀는 조심성 있는 운전자이다. 그녀는 조심스럽게 운전한다."], ["He speaks English well.", "그는 영어를 잘 말한다."]],
      warn: 'friendly, lovely는 -ly로 끝나지만 형용사이다. hardly는 "거의 ~않다"라는 뜻이라 hard(열심히)와 다르다.' },
    { h: '빈도부사',
      p: '얼마나 자주 하는지를 나타내는 부사를 빈도부사라고 한다. 빈도부사는 <span class="hl">be동사·조동사 뒤, 일반동사 앞</span>에 온다.',
      table: { head: ['빈도부사', '뜻', '예문'], rows: [['always', '항상', 'I always get up at seven.'], ['usually', '보통', 'She usually walks to school.'], ['often', '자주', 'We often play badminton.'], ['sometimes', '가끔', 'He is sometimes late.'], ['never', '결코 ~않다', 'They never eat fast food.']] },
      ex: [["He is never late for school.", "그는 절대 학교에 늦지 않는다."], ["I usually have cereal for breakfast.", "나는 보통 아침으로 시리얼을 먹는다."]] },
    { h: '비교 기초: 원급, 비교급, 최상급',
      p: '둘이 같으면 <span class="hl">as + 원급 + as</span>, 둘 중 하나가 더하면 <span class="hl">비교급 + than</span>, 셋 이상 중 가장 ~하면 <span class="hl">the + 최상급</span>을 쓴다. 짧은 단어는 -er / -est, 긴 단어는 more / most를 붙인다.',
      table: { head: ['원급', '비교급', '최상급', '규칙'], rows: [['tall', 'taller', 'tallest', '+er / +est'], ['large', 'larger', 'largest', '+r / +st'], ['heavy', 'heavier', 'heaviest', 'y → ier / iest'], ['big', 'bigger', 'biggest', '자음 한 번 더'], ['beautiful', 'more beautiful', 'most beautiful', '긴 단어'], ['good / well', 'better', 'best', '불규칙']] },
      ex: [["My bag is as heavy as yours.", "내 가방은 네 것만큼 무겁다."], ["Jiho is taller than Minsu.", "지호는 민수보다 키가 크다."], ["Seoul is the biggest city in Korea.", "서울은 한국에서 가장 큰 도시이다."]] },
  ],
  bank: [
    { lv: 1, q: 'happy의 부사형으로 알맞은 것은?', o: ['happyly', 'happily', 'happly', 'happiness'], a: 1, why: '자음 + y로 끝나는 형용사는 y를 i로 고치고 -ly를 붙인다. happiness는 명사이다.' },
    { lv: 1, q: 'tall의 비교급으로 알맞은 것은?', o: ['taller', 'more tall', 'tallest', 'tall than'], a: 0, why: '짧은 형용사는 -er을 붙여 비교급을 만든다. tallest는 최상급이다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>He is a ___ runner.', o: ['fastly', 'quickly', 'fast', 'well'], a: 2, why: '명사 runner를 꾸미므로 형용사가 필요하다. fast는 형용사로도 쓴다. fastly라는 단어는 없다.' },
    { lv: 2, q: '빈도부사의 위치가 올바른 문장은?', o: ['She always is kind.', 'I go always to bed at ten.', 'He is never late for school.', 'They play usually soccer.'], a: 2, why: '빈도부사는 be동사 뒤, 일반동사 앞에 온다. She is always kind., I always go ..., They usually play ...가 맞다.' },
    { lv: 2, q: 'big의 최상급으로 알맞은 것은?', o: ['bigest', 'most big', 'bigger', 'biggest'], a: 3, why: 'big은 단모음 + 단자음이므로 g를 한 번 더 쓰고 -est를 붙인다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>This box is ___ than that one. (heavy)', o: ['heavyer', 'heavier', 'more heavy', 'heaviest'], a: 1, why: 'than이 있으므로 비교급이고, 자음 + y는 y를 i로 고쳐 heavier가 된다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['He speaks English good.', 'She sings beautifully.', 'This question is easy.', 'My dog runs very fast.'], a: 0, why: '동사 speaks를 꾸미므로 부사 well이 필요하다. good은 형용사이다.' },
    { lv: 3, q: '우리말과 뜻이 같은 문장은?<br>나의 가방은 너의 것만큼 무겁다.', o: ['My bag is as heavier as yours.', 'My bag is as heavy as yours.', 'My bag is heavy as yours.', 'My bag is as heavy than yours.'], a: 1, why: '"~만큼 …한"은 as + 원급 + as이다. as 사이에 비교급을 쓰거나 than을 쓰지 않는다.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['Seoul is the bigger city in Korea.', 'She is more pretty than her sister.', 'This is the most fast car.', 'He studies hard every day.'], a: 3, why: 'hard는 형용사와 부사의 모양이 같다. the biggest, prettier, the fastest로 고쳐야 한다.' },
    { lv: 4, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Minsu, Jiho, and Daniel are good friends. Minsu is 160 cm tall. Jiho is 165 cm tall, and Daniel is 170 cm tall. Jiho is the oldest of the three. He is fifteen. Minsu and Daniel are both fourteen. Daniel runs faster than Jiho, but Minsu is the fastest runner in their class.</div>`, o: ['민수가 셋 중 가장 키가 크다.', '지호는 대니얼보다 키가 크다.', '민수와 대니얼은 나이가 같다.', '지호가 셋 중 가장 빨리 달린다.'], a: 2, why: 'Minsu and Daniel are both fourteen.이라고 했다. 키는 대니얼이 가장 크고, 가장 빠른 사람은 민수이다.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">I have a busy week. I always get up at seven. I usually walk to school, but I sometimes take the bus on rainy days. I often play badminton with my friends after school. I never eat fast food because it isn't good for my health. On Sundays, I usually help my mom in the kitchen.</div>`, o: ['항상 7시에 일어난다.', '비 오는 날에는 가끔 버스를 탄다.', '방과 후에 자주 배드민턴을 친다.', '가끔 패스트푸드를 먹는다.'], a: 3, why: 'I never eat fast food.라고 했으므로 패스트푸드를 전혀 먹지 않는다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">My grandmother is a <u>①&nbsp;wonderful</u> cook. She makes <u>②&nbsp;delicious</u> food for our family. Her kimchi is <u>③&nbsp;better</u> than any kimchi in the store. She always cooks <u>④&nbsp;careful</u> and slowly. When I visit her, she gives me a big hug.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '동사 cooks를 꾸미므로 부사 carefully가 와야 한다. ③ better는 good의 비교급으로 맞다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Last Saturday, our class had a race. The weather was (A) [nice / nicely]. I ran (B) [quick / quickly], but Yuri ran even faster. She is the (C) [faster / fastest] runner in our school. I wasn't sad. I want to practice hard and run like her next year.</div>`, o: ['nicely – quickly – fastest', 'nice – quickly – fastest', 'nice – quick – fastest', 'nice – quickly – faster'], a: 1, why: '(A) be동사 뒤 보어 → 형용사 nice. (B) 동사 ran을 꾸밈 → 부사 quickly. (C) the ~ in our school → 최상급 fastest.' },
    { lv: 5, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Junho went to Happy Mart to buy some fruit for his family. At the store, an apple was 1,000 won, a banana was 500 won, and a mango was 3,000 won. Junho had 5,000 won. He bought two apples and two bananas. His sister wanted a mango, but he didn't have enough money left.</div>`, o: ['A banana was more expensive than an apple.', 'An apple was as cheap as a banana.', 'A mango was the most expensive of the three.', 'An apple was cheaper than a banana.'], a: 2, why: '망고(3,000원)가 세 과일 중 가장 비싸다. 바나나(500원)는 사과(1,000원)보다 싸다.' },
    { lv: 5, q: `글쓴이가 시골을 더 좋아하는 이유로 알맞은 것은?<div class="passage">Many people ask me, "Which is better, the city or the countryside?" I lived in both. The city is more exciting than the countryside. There are many stores and shows. But the countryside is quieter and cleaner. The air is fresher, too. For me, the countryside is better because I like peace.</div>`, o: ['평화로운 것을 좋아해서', '도시보다 더 신나서', '가게가 많아서', '공연이 많아서'], a: 0, why: 'the countryside is better because I like peace라고 했다. 신나고 가게·공연이 많은 것은 도시의 장점이다.' },
  ],
});

ENG.add('m1', '독해: 글의 주제 찾기', {
  sub: '처음·반복어·신호어로 중심 생각 잡기',
  kw: ['주제', '제목', '요지', '주제문', '반복 어휘', '신호어', 'However', '오답 함정'],
  sections: [
    { h: '주제·제목·요지란?',
      p: '<b>주제</b>는 글이 "무엇에 대해" 말하는지, <b>요지</b>는 글쓴이가 "결국 하고 싶은 말"이 무엇인지, <b>제목</b>은 주제를 짧고 눈에 띄게 나타낸 것이다. 한 문단에는 보통 중심 생각을 담은 <span class="hl">주제문</span>이 하나 있고, 나머지 문장은 예시나 이유로 주제문을 뒷받침한다.',
      ex: [["Exercise is good for your mind, too.", "운동은 마음에도 좋다. (주제문)"], ["For example, a short walk can reduce stress.", "예를 들어, 짧은 산책은 스트레스를 줄일 수 있다. (뒷받침 문장)"]],
      tip: '주제는 보통 "~의 중요성", "~하는 방법", "~의 이유"처럼 명사구로 나타낸다.' },
    { h: '주제 찾기 풀이 순서',
      p: '주제 문제는 글을 처음부터 끝까지 꼼꼼히 해석하기보다, 중심 생각이 숨어 있는 곳을 먼저 확인하는 것이 빠르다.',
      table: { head: ['순서', '할 일', '확인할 점'], rows: [['1', '첫 한두 문장 읽기', '무엇에 대한 글인지(화제) 잡기'], ['2', '반복되는 낱말 찾기', '여러 번 나오는 말이 주제의 핵심어'], ['3', '신호어 뒤 확인', 'But, However, So 뒤에 글쓴이의 생각이 온다'], ['4', '마지막 문장 확인', '결론·정리 문장이 주제문인 경우가 많다'], ['5', '보기 고르기', '너무 넓거나 좁은 보기, 글에 없는 보기 지우기']], cap: '주제 찾기 5단계' },
      p2: '예시(For example) 뒤의 문장은 주제가 아니라 주제를 뒷받침하는 내용이다.' },
    { h: '신호어와 오답 함정',
      p: '신호어는 글의 흐름을 알려 주는 말이다. 특히 <span class="hl">But, However</span> 뒤에는 앞의 내용을 뒤집는 글쓴이의 진짜 생각이 오는 경우가 많다.',
      table: { head: ['신호어', '뜻', '주제와의 관계'], rows: [['But / However', '그러나', '뒤에 중심 생각이 오는 경우가 많다'], ['So / That\'s why', '그래서 / 그것이 ~한 이유다', '결론·요지'], ['For example', '예를 들어', '뒤는 예시(주제 아님)'], ['First, Second, Also', '첫째, 둘째, 또한', '방법·이유를 나열'], ['I think / We should', '나는 ~라고 생각한다 / ~해야 한다', '글쓴이의 주장']] },
      warn: '오답 함정: ① 글에 나온 낱말 하나만 쓴 보기(너무 좁음) ② "모든 동물"처럼 너무 넓은 보기 ③ 그럴듯하지만 글에 없는 보기' },
  ],
  bank: [
    { lv: 1, q: `다음 문장들의 공통 화제로 알맞은 것은?<div class="passage">Dogs are friendly. Cats are cute. Rabbits are soft. Many people keep these animals at home.</div>`, o: ['food', 'pets', 'sports', 'weather'], a: 1, why: '개, 고양이, 토끼를 집에서 키운다고 했으므로 공통 화제는 애완동물(pets)이다.' },
    { lv: 1, q: '글의 주제를 찾을 때 가장 먼저 읽으면 좋은 부분은?', o: ['마지막 낱말 하나', '가장 긴 낱말', '숫자가 나오는 문장', '글의 첫 한두 문장'], a: 3, why: '첫 한두 문장에서 글이 무엇에 대한 것인지 화제를 잡을 수 있다.' },
    { lv: 1, q: '뒤에 글쓴이의 중심 생각이 이어지는 경우가 많은 신호어는?', o: ['However', 'For example', 'Also', 'First'], a: 0, why: 'However(그러나) 뒤에는 앞의 내용을 뒤집는 중심 생각이 자주 온다. For example 뒤는 예시이다.' },
    { lv: 2, q: `다음 글의 주제로 알맞은 것은?<div class="passage">Water is very important for our body. It keeps our body cool. It also helps us digest food. So drink enough water every day.</div>`, o: ['the taste of water', 'how to cook with water', 'the importance of water for our body', 'where to buy water'], a: 2, why: '첫 문장이 주제문이고, 나머지는 물이 중요한 이유와 결론이다.' },
    { lv: 2, q: `다음 글의 요지로 알맞은 것은?<div class="passage">Some people think breakfast is not important. However, breakfast gives us energy for the morning. Students who eat breakfast can focus better in class.</div>`, o: ['아침을 먹으면 살이 찐다.', '아침 식사는 중요하다.', '점심이 아침보다 중요하다.', '아침 메뉴는 다양해야 한다.'], a: 1, why: 'However 뒤에 아침 식사가 에너지를 주고 집중을 돕는다는 글쓴이의 생각이 나온다.' },
    { lv: 2, q: `다음 글의 주제로 알맞은 것은?<div class="passage">My favorite season is fall. The weather is cool, and the leaves turn red and yellow. I also love the fruit of fall, like apples and persimmons.</div>`, o: ['four seasons in Korea', 'red and yellow leaves', 'how to grow apples', 'why I love fall'], a: 3, why: '가을을 좋아하는 이유를 나열한 글이다. ①은 너무 넓고, ②는 일부만 다룬 좁은 보기이다.' },
    { lv: 3, q: `다음 글에서 주제문은?<div class="passage">① Many students use smartphones every day. ② But using smartphones too much can be bad for you. ③ It can hurt your eyes. ④ It can also make you sleep badly.</div>`, o: ['①', '②', '③', '④'], a: 1, why: 'But 뒤의 ②가 중심 생각이고, ③과 ④는 그 이유를 들어 뒷받침한다.' },
    { lv: 3, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">Bees are small, but they do a big job. They carry pollen from flower to flower. This helps plants make fruit and seeds. Without bees, we could not have many fruits and vegetables.</div>`, o: ['How to Avoid Bee Stings', 'The Biggest Flowers', 'Bees: Small Insects with a Big Job', 'Seeds of Vegetables'], a: 2, why: '첫 문장 "작지만 큰 일을 한다"가 주제문이며 벌의 중요한 역할을 설명한다.' },
    { lv: 3, q: `다음 글의 주제로 알맞은 것은?<div class="passage">Recycling is easy. First, wash the bottles and cans. Then, put paper, plastic, and glass in different boxes. If everyone does this, we can make our earth cleaner.</div>`, o: ['ways to recycle at home', 'the history of glass', 'how to make paper', 'why cans are heavy'], a: 0, why: 'First, Then으로 재활용하는 방법을 순서대로 설명한다.' },
    { lv: 4, q: `다음 글의 주제로 가장 알맞은 것은?<div class="passage">Do you know how to make new friends? First, smile and say hello. A smile makes people feel comfortable. Second, ask questions about their hobbies. People like to talk about things they enjoy. Third, listen carefully. Good listeners are good friends. Try these tips, and you will make many new friends at your new school.</div>`, o: ['the importance of hobbies', 'ways to make new friends', 'why smiling is healthy', 'how to choose a school'], a: 1, why: '첫 문장에서 화제를 던지고 First, Second, Third로 친구를 사귀는 방법을 나열한다. ①, ③은 일부 내용만 다룬다.' },
    { lv: 4, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">Many people think fish don't sleep. That's because fish don't have eyelids, so they can't close their eyes. However, scientists say fish do rest. They slow down and stay in one place for a while. Some fish even hide under rocks at night. So fish sleep too, just in a different way.</div>`, o: ['물고기에게는 눈꺼풀이 없다.', '물고기는 밤에 먹이를 찾는다.', '과학자들은 물고기를 좋아한다.', '물고기도 나름의 방식으로 잠을 잔다.'], a: 3, why: 'However 뒤와 마지막 So 문장에서 물고기도 다른 방식으로 잔다는 요지를 밝힌다. ①은 세부 내용일 뿐이다.' },
    { lv: 4, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">Every year on April 5, many Koreans plant trees. Trees give us clean air. They also give homes to birds and insects. In summer, they give us cool shade. That's why planting trees is a great way to protect nature. This year, why don't you plant a tree with your family?</div>`, o: ["Let's Plant Trees!", 'The Life of Insects', 'Hot Summer Days', 'Famous Korean Holidays'], a: 0, why: '나무의 좋은 점을 나열한 뒤 That\'s why ~와 마지막 문장에서 나무를 심자고 권한다.' },
    { lv: 5, q: `다음 글의 주제로 가장 알맞은 것은?<div class="passage">Many students feel stressed before tests. Here is some good news: there are easy ways to feel better. Taking a short walk can clear your mind. Listening to calm music can also help. Most of all, getting enough sleep is very important. When you sleep well, your brain remembers things better. Don't stay up all night before a test!</div>`, o: ['why tests are difficult', 'the history of music', 'ways to reduce stress before tests', 'how the brain grows'], a: 2, why: '시험 전 스트레스를 줄이는 방법(산책, 음악, 충분한 잠)을 소개하는 글이다.' },
    { lv: 5, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">Some people say video games are a waste of time. Of course, playing games for too many hours is not good. However, some games can be helpful. Puzzle games help players think carefully. Team games teach them how to work with others. The important thing is to play for a short time and choose good games.</div>`, o: ['좋은 게임을 골라 짧게 하면 도움이 될 수 있다.', '게임은 시간 낭비일 뿐이다.', '게임을 전혀 하지 말아야 한다.', '팀 게임이 퍼즐 게임보다 재미있다.'], a: 0, why: 'However 뒤에서 게임의 장점을 말하고, 마지막 문장에서 짧게, 좋은 게임을 고르라고 정리한다. ②는 글쓴이가 반박하는 남의 생각이다.' },
    { lv: 5, q: `다음 글에서 전체 흐름과 관계<b>없는</b> 문장은?<div class="passage">Pandas spend most of their day eating. ① They eat bamboo for about twelve hours a day. ② Bamboo does not have much energy, so they need to eat a lot of it. ③ My favorite animal at the zoo is the giraffe. ④ After eating, they often take a long rest to save energy.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '판다가 하루 대부분을 먹으며 보낸다는 글인데, ③은 글쓴이가 좋아하는 기린 이야기로 주제와 관계없다.' },
  ],
});

ENG.add('m2', 'to부정사', {
  sub: 'to + 동사원형의 명사·형용사·부사적 쓰임',
  kw: ['to부정사', '명사적 용법', '가주어 it', '형용사적 용법', '부사적 용법', '목적', '감정의 원인', '의문사 + to부정사'],
  sections: [
    { h: 'to부정사의 세 가지 쓰임',
      p: 'to부정사는 <span class="hl">to + 동사원형</span>의 형태로, 문장 안에서 명사·형용사·부사처럼 쓰인다. 같은 모양이라도 문장에서 하는 역할을 보고 용법을 판단해야 한다.',
      table: { head: ['용법', '역할 / 해석', '예문'], rows: [['명사적', '주어·목적어·보어 (~하는 것)', 'I want to be a doctor.'], ['형용사적', '명사 뒤에서 수식 (~할, ~하는)', 'I have no time to play games.'], ['부사적 – 목적', '~하기 위해', 'He went to Paris to study art.'], ['부사적 – 감정의 원인', '~해서 (happy, sad, glad 뒤)', 'I was happy to hear the news.'], ['부사적 – 결과', '(자라서) ~하게 되다', 'She grew up to be a pilot.']], cap: 'to부정사 용법 정리' },
      ex: [["My dream is to travel around the world.", "내 꿈은 세계를 여행하는 것이다."], ["Do you have anything to eat?", "먹을 것이 있니?"]] },
    { h: '명사적 용법과 가주어 it',
      p: 'to부정사가 주어일 때는 문장이 길어지므로 주어 자리에 <span class="hl">it</span>을 두고 to부정사를 뒤로 보내는 경우가 많다. 이때 it은 뜻이 없는 가주어이다. want, hope, decide, plan, need 같은 동사는 to부정사를 목적어로 쓴다.',
      ex: [["It is fun to play soccer with friends.", "친구들과 축구하는 것은 재미있다."], ["It is not easy to learn a new language.", "새 언어를 배우는 것은 쉽지 않다."], ["She decided to study abroad.", "그녀는 유학하기로 결심했다."]],
      tip: 'It ~ to ... 문장에서 it을 "그것"으로 해석하지 않는다.' },
    { h: '형용사적 용법과 전치사',
      p: '형용사적 용법의 to부정사는 <b>명사 뒤</b>에서 명사를 꾸민다. -thing으로 끝나는 말에 형용사도 함께 쓰면 <span class="hl">-thing + 형용사 + to부정사</span> 순서가 된다. 꾸밈을 받는 명사가 전치사의 목적어이면 to부정사 뒤에 전치사를 남겨야 한다.',
      ex: [["I want something cold to drink.", "나는 차가운 마실 것을 원한다."], ["He needs a chair to sit on.", "그는 앉을 의자가 필요하다. (sit on a chair)"], ["She has many friends to talk with.", "그녀는 함께 이야기할 친구가 많다."]],
      warn: 'a chair to sit (×) → a chair to sit on (○), a pen to write (×) → a pen to write with (○)' },
    { h: '의문사 + to부정사',
      p: '<span class="hl">의문사 + to부정사</span>는 "~해야 할지"라는 뜻으로 명사처럼 쓰여 know, learn, tell 등의 목적어가 된다.',
      table: { head: ['표현', '뜻', '예문'], rows: [['how to + 동사원형', '어떻게 ~할지, ~하는 방법', 'I learned how to swim.'], ['what to + 동사원형', '무엇을 ~할지', "I don't know what to wear."], ['where to + 동사원형', '어디서 ~할지', 'Tell me where to go.'], ['when to + 동사원형', '언제 ~할지', 'He asked when to start.']] },
      ex: [["Can you show me how to use this machine?", "이 기계 사용하는 법을 보여 줄래?"]] },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I want ___ a doctor.', o: ['be', 'to be', 'being', 'am'], a: 1, why: 'want는 to부정사를 목적어로 쓴다.' },
    { lv: 1, q: 'to부정사의 형태로 알맞은 것은?', o: ['to + 동사원형', 'to + -ing', 'to + 과거형', 'to + 명사'], a: 0, why: 'to부정사는 to 뒤에 항상 동사원형을 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I don\'t know how ___ this machine.', o: ['use', 'using', 'to use', 'used'], a: 2, why: '"~하는 방법"은 how + to부정사로 나타낸다.' },
    { lv: 2, q: '밑줄 친 to부정사의 용법이 나머지 셋과 <b>다른</b> 것은?', o: ['I hope <u>to see</u> you again.', 'She decided <u>to study</u> abroad.', 'I have no time <u>to play</u> games.', 'He wants <u>to buy</u> a new bike.'], a: 2, why: '③은 명사 time을 꾸미는 형용사적 용법이고, 나머지는 동사의 목적어인 명사적 용법이다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>It is fun ___ soccer with friends.', o: ['play', 'to play', 'plays', 'played'], a: 1, why: 'It은 가주어이고 진주어 자리에 to부정사가 온다.' },
    { lv: 2, q: '두 문장을 한 문장으로 바르게 바꾼 것은?<br>I went to the store. I wanted to buy milk.<br>= I went to the store ___ milk.', o: ['buy', 'to buying', 'bought', 'to buy'], a: 3, why: '"우유를 사기 위해"라는 목적을 나타내므로 부사적 용법 to buy를 쓴다.' },
    { lv: 3, q: '밑줄 친 to부정사가 형용사적 용법으로 쓰인 것은?', o: ['I was happy <u>to hear</u> the news.', '<u>To swim</u> in the sea is exciting.', 'Do you have anything <u>to eat</u>?', 'He went to Paris <u>to study</u> art.'], a: 2, why: 'to eat이 anything을 꾸며 "먹을 것"이 된다. ①은 감정의 원인, ②는 주어, ④는 목적이다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['He needs a chair to sit.', 'I need a pen to write with.', 'She has many friends to talk with.', 'I want something cold to drink.'], a: 0, why: '"의자 위에 앉다"는 sit on a chair이므로 a chair to sit on이라고 해야 한다.' },
    { lv: 3, q: '우리말과 뜻이 같은 문장은?<br>나는 무엇을 입어야 할지 모르겠다.', o: ["I don't know what wear.", "I don't know what to wear.", "I don't know to wear what.", "I don't know what wearing."], a: 1, why: '"무엇을 ~할지"는 what + to부정사이다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Last winter, Jaemin decided (A) <span class="blank"></span> a new hobby. He wanted to do something special, so he chose baking. At first, it was not easy (B) <span class="blank"></span> good bread. His bread was often too hard. But he didn't give up. He watched videos to learn tips and practiced every weekend. Now his family loves his bread. Jaemin says, "I was so happy (C) <span class="blank"></span> my parents smile when they ate my bread."</div>`, o: ['to start – make – see', 'to start – to make – to see', 'starting – to make – seeing', 'to start – to make – seeing'], a: 1, why: '(A) decide는 to부정사를 목적어로 쓴다. (B) 가주어 it의 진주어 to make. (C) 감정(happy)의 원인 to see.' },
    { lv: 4, q: `밑줄 친 ⓐ와 용법이 같은 것은?<div class="passage">Hyeri goes to the library every Saturday. She goes there <u>ⓐ&nbsp;to borrow</u> books about space. She wants <u>ⓑ&nbsp;to become</u> an astronaut someday. Her room is full of books, but she still has a lot of books <u>ⓒ&nbsp;to read</u>. Last month, she saved her allowance <u>ⓓ&nbsp;to visit</u> a science center in Daejeon. There, she learned how planets move around the sun. "It was the best day of my life," she said.</div>`, o: ['ⓑ', 'ⓒ', 'ⓓ', 'ⓑ, ⓒ'], a: 2, why: 'ⓐ는 "빌리기 위해"라는 목적(부사적 용법)이다. ⓓ도 "방문하기 위해"라는 목적이다. ⓑ는 목적어(명사적), ⓒ는 books를 꾸미는 형용사적 용법이다.' },
    { lv: 4, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Many teens find it hard to wake up early. Scientists say there is a reason for this. Teenagers' bodies make a sleep hormone later at night than adults' bodies do. So it is natural for them to feel sleepy late in the morning. Some schools in other countries decided to start classes later. As a result, students were less tired and got better grades.</div>`, o: ['10대는 성인보다 수면 호르몬이 일찍 나온다.', '모든 나라의 학교가 수업을 늦게 시작한다.', '수업을 늦게 시작하자 성적이 떨어졌다.', '10대가 아침 늦게까지 졸린 것은 자연스러운 일이다.'], a: 3, why: 'it is natural for them to feel sleepy late in the morning이라고 했다. 호르몬은 더 늦게 나오고, 일부 학교만 수업을 늦췄으며 성적은 올랐다.' },
    { lv: 5, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Do you want <u>①&nbsp;to keep</u> your room clean? Here are some tips. First, decide where <u>②&nbsp;to put</u> each thing. A box for small things is very useful. Second, it is a good idea <u>③&nbsp;throw</u> away things you don't use anymore. Third, make a rule <u>④&nbsp;to clean</u> your desk every night. If you follow these tips, you won't need much time to find your things.</div>`, o: ['①', '②', '③', '④'], a: 2, why: 'it은 가주어이므로 진주어 자리에 to throw가 와야 한다. ②는 의문사 + to부정사, ④는 rule을 꾸미는 형용사적 용법이다.' },
    { lv: 5, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">When I was in elementary school, I was very shy. It was hard for me (A) <span class="blank"></span> in front of the class. One day, my teacher gave me a chance (B) <span class="blank"></span> a short story to my classmates. I practiced many times at home (C) <span class="blank"></span> well. On that day, my voice was shaking, but my classmates clapped for me. Since then, I have become more confident.</div>`, o: ['speak – to read – to do', 'to speak – reading – to do', 'to speak – to read – doing', 'to speak – to read – to do'], a: 3, why: '(A) 가주어 it의 진주어 to speak. (B) chance를 꾸미는 형용사적 용법 to read. (C) "잘하기 위해" 목적 to do.' },
    { lv: 5, q: `다음 글의 주제로 가장 알맞은 것은?<div class="passage">Some people only think about their dreams but never act. Writing down your goals is a good way to make them real. When you write them, you see clearly what to do next. It's also helpful to break a big goal into small steps. For example, if you want to run a marathon, start by running one kilometer a day. Small steps will take you to your big dream.</div>`, o: ['ways to make your goals real', 'the history of the marathon', 'why dreams are not important', 'how to write a story'], a: 0, why: '목표를 적고, 큰 목표를 작은 단계로 나누는 등 꿈을 현실로 만드는 방법을 설명한다. 마라톤은 예시일 뿐이다.' },
  ],
});

ENG.add('m2', '동명사', {
  sub: '동사 + -ing가 명사처럼 쓰이는 경우',
  kw: ['동명사', '-ing', 'enjoy / finish / mind', 'want / hope / decide', 'remember / forget', 'stop', '전치사 + 동명사', 'look forward to'],
  sections: [
    { h: '동명사의 형태와 역할',
      p: '동명사는 <span class="hl">동사원형 + -ing</span>로 "~하는 것, ~하기"라는 뜻이며, 명사처럼 문장에서 주어, 목적어, 보어로 쓰인다. 특히 <b>전치사 뒤</b>에는 to부정사가 아니라 동명사를 쓴다.',
      table: { head: ['역할', '예문', '해석'], rows: [['주어', 'Reading books is my hobby.', '책 읽는 것은 내 취미이다.'], ['동사의 목적어', 'I enjoy listening to music.', '나는 음악 듣는 것을 즐긴다.'], ['보어', 'My job is teaching children.', '내 일은 아이들을 가르치는 것이다.'], ['전치사의 목적어', 'Thank you for helping me.', '도와줘서 고마워.']] },
      tip: '동명사 주어는 단수 취급한다. Reading books is ... (○) / are (×)' },
    { h: '목적어로 동명사를 쓰는 동사, to부정사를 쓰는 동사',
      p: '동사에 따라 목적어로 동명사만, to부정사만, 또는 둘 다 쓸 수 있다. 대체로 이미 하고 있거나 한 일에는 동명사, 앞으로 할 일에는 to부정사를 쓰는 경향이 있다.',
      table: { head: ['목적어', '동사', '예문'], rows: [['동명사만', 'enjoy, finish, mind, give up, avoid, keep, practice', 'He finished doing his homework.'], ['to부정사만', 'want, hope, decide, plan, need, promise, wish', 'She hopes to win the game.'], ['둘 다 (뜻 같음)', 'like, love, hate, start, begin', 'It started raining. = It started to rain.']], cap: '목적어에 따른 동사 구분' },
      ex: [["Would you mind opening the window?", "창문 좀 열어 주시겠어요?"], ["He gave up smoking.", "그는 담배를 끊었다."]] },
    { h: '뜻이 달라지는 동사: remember, forget, stop, try',
      p: '어떤 동사는 뒤에 동명사가 오느냐 to부정사가 오느냐에 따라 뜻이 달라진다. <span class="hl">동명사는 과거에 한 일</span>, <span class="hl">to부정사는 앞으로 할 일</span>로 생각하면 쉽다. stop 뒤의 to부정사는 목적어가 아니라 "~하기 위해"라는 부사적 용법이다.',
      table: { head: ['동사', '+ 동명사', '+ to부정사'], rows: [['remember', '(과거에) ~한 것을 기억하다', '(앞으로) ~할 것을 기억하다'], ['forget', '(과거에) ~한 것을 잊다', '(앞으로) ~할 것을 잊다'], ['stop', '~하는 것을 멈추다', '~하기 위해 멈추다'], ['try', '시험 삼아 ~해 보다', '~하려고 애쓰다']] },
      ex: [["I remember sending the letter.", "나는 그 편지를 보낸 것을 기억한다."], ["Remember to send the letter.", "편지 보낼 것을 기억해라."], ["He stopped to drink water.", "그는 물을 마시기 위해 멈췄다."]] },
    { h: '동명사 관용 표현',
      p: '동명사를 쓰는 굳어진 표현은 통째로 익혀 두는 것이 좋다. look forward to의 to는 전치사이므로 뒤에 동명사가 온다.',
      table: { head: ['표현', '뜻'], rows: [['go -ing', '~하러 가다 (go hiking, go swimming)'], ['be good at -ing', '~을 잘하다'], ['How about -ing?', '~하는 게 어때?'], ['look forward to -ing', '~하기를 고대하다'], ['be busy -ing', '~하느라 바쁘다'], ['feel like -ing', '~하고 싶다']] },
      ex: [["I'm looking forward to seeing you.", "너를 만나기를 고대하고 있어."], ["She is busy preparing for the test.", "그녀는 시험 준비하느라 바쁘다."]],
      warn: "look forward to see (×) → look forward to seeing (○)" },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I enjoy ___ to music.', o: ['listen', 'to listen', 'listening', 'listened'], a: 2, why: 'enjoy는 동명사를 목적어로 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>Thank you for ___ me.', o: ['help', 'helping', 'to help', 'helped'], a: 1, why: '전치사 for 뒤에는 동명사를 쓴다.' },
    { lv: 1, q: '목적어로 동명사를 쓰는 동사는?', o: ['want', 'hope', 'decide', 'finish'], a: 3, why: 'finish는 동명사를 목적어로 쓴다. want, hope, decide는 to부정사를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>My uncle gave up ___ last year.', o: ['smoking', 'to smoke', 'smoke', 'smoked'], a: 0, why: 'give up은 동명사를 목적어로 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>How about ___ out for dinner?', o: ['go', 'to go', 'going', 'went'], a: 2, why: 'How about 뒤에는 동명사가 온다. about은 전치사이다.' },
    { lv: 2, q: '빈칸에 들어갈 수 <b>없는</b> 것은?<br>I ___ playing the guitar.', o: ['like', 'enjoy', 'practice', 'want'], a: 3, why: 'want는 to부정사만 목적어로 쓰므로 want playing은 틀린다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['Reading books is my hobby.', 'She is good at drawing.', "I'm looking forward to see you.", 'He kept talking during class.'], a: 2, why: 'look forward to의 to는 전치사이므로 seeing을 써야 한다.' },
    { lv: 3, q: '<b>I stopped to drink water.</b>의 뜻으로 알맞은 것은?', o: ['나는 물 마시는 것을 멈췄다.', '나는 물을 마시기 위해 멈췄다.', '나는 물을 마시지 않았다.', '나는 물을 마시고 싶었다.'], a: 1, why: 'stop + to부정사는 "~하기 위해 멈추다"이다. "마시는 것을 멈췄다"는 stopped drinking이다.' },
    { lv: 3, q: '우리말과 뜻이 같은 문장은?<br>나는 그 편지를 보낸 것을 기억한다.', o: ['I remember to send the letter.', 'I remember send the letter.', 'I remember sent the letter.', 'I remember sending the letter.'], a: 3, why: '과거에 한 일을 기억할 때는 remember + 동명사를 쓴다. remember to send는 "보낼 것을 기억하다"이다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">My older brother, Junseo, loves (A) <span class="blank"></span> photos. He started this hobby when he was twelve. Every weekend, he goes (B) <span class="blank"></span> in the mountains with his camera. He is especially good at (C) <span class="blank"></span> pictures of birds. He says waiting for a bird for hours is not boring at all. Last month, one of his photos won a prize in a contest. Now he is looking forward to joining a photo club in high school.</div>`, o: ['take – hike – taking', 'taking – hiking – taking', 'taking – hiking – take', 'to take – hiking – to take'], a: 1, why: '(A) love는 동명사·to부정사 모두 가능 → taking. (B) go -ing → hiking. (C) 전치사 at 뒤 → taking. ④는 at 뒤에 to take를 써서 틀린다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Yesterday, Sena came home from school and found her bedroom window wide open. "Mom, did you open my window?" she asked. "No, I didn't," Mom said. Then Sena remembered (A) <span class="blank"></span> it herself in the morning. She was in a hurry and forgot (B) <span class="blank"></span> it before she left. "Sorry, Mom. I'll remember (C) <span class="blank"></span> my window from now on."</div>`, o: ['opening – to close – to close', 'to open – to close – closing', 'opening – closing – to close', 'to open – closing – closing'], a: 0, why: '(A) 아침에 이미 연 것을 기억 → opening. (B) 닫아야 할 것을 잊음 → to close. (C) 앞으로 닫을 것을 기억 → to close.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Laughing is good for your health. When you laugh, your body relaxes. Laughing also helps your heart by moving more blood through your body. Some doctors even say that laughing for fifteen minutes a day is like walking for a short time. So try watching a funny movie or sharing jokes with your friends. Don't stop laughing!</div>`, o: ['웃으면 몸이 이완된다.', '웃음은 심장 건강에 도움이 된다.', '의사들은 웃음보다 걷기를 더 권한다.', '하루 15분 웃는 것은 짧게 걷는 것과 비슷하다고 한다.'], a: 2, why: '웃음이 짧은 걷기와 비슷하다고 했을 뿐, 걷기를 더 권한다는 내용은 없다.' },
    { lv: 5, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Minho has a problem. He can't stop <u>①&nbsp;playing</u> games on his phone. Last night, he kept <u>②&nbsp;to play</u> until two in the morning. In class the next day, he couldn't focus on <u>③&nbsp;listening</u> to the teacher. So he decided <u>④&nbsp;to change</u> his habit. Now he puts his phone in the living room before going to bed. He feels much better these days.</div>`, o: ['①', '②', '③', '④'], a: 1, why: 'keep은 동명사를 목적어로 쓰므로 kept playing이 맞다. ③은 전치사 on 뒤, ④는 decide + to부정사로 맞다.' },
    { lv: 5, q: `밑줄 친 <u>tried drinking</u>의 의미로 가장 알맞은 것은?<div class="passage">Last month, I had trouble sleeping. I went to bed at eleven, but I was still awake at two. My friend gave me some advice. First, I stopped using my phone an hour before bed. Then I <u>tried drinking</u> a glass of warm milk at night, just to see what would happen. Surprisingly, it worked! Now I fall asleep easily, and I feel fresh in the morning.</div>`, o: ['마시려고 애썼다', '마시는 것을 멈췄다', '시험 삼아 마셔 보았다', '마시는 것을 잊었다'], a: 2, why: 'try + 동명사는 "시험 삼아 ~해 보다"이다. just to see what would happen(어떻게 되는지 보려고)도 단서이다.' },
    { lv: 5, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">Have you ever thought about walking to school instead of taking the bus? Walking has many benefits. First, it keeps your body healthy. Second, it saves money and protects the environment. Also, walking with friends gives you time to talk and have fun. You don't have to walk every day. Start by walking once or twice a week, and you will enjoy it.</div>`, o: ['Why Buses Are Fast', 'How to Make Friends', 'Saving Money with Cars', 'The Benefits of Walking to School'], a: 3, why: 'Walking has many benefits.가 주제문이고 건강, 돈 절약, 환경, 친구와의 시간 등 걸어서 등교하는 장점을 나열한다.' },
  ],
});

ENG.add('m2', '수동태 기초', {
  sub: '"~되다, ~받다"를 be + 과거분사로',
  kw: ['수동태', 'be + p.p.', 'by + 행위자', '과거분사', '시제별 수동태', '수동태 의문문', 'be covered with', 'be made of'],
  sections: [
    { h: '수동태의 형태와 만드는 법',
      p: '주어가 동작을 직접 하면 능동태, 주어가 동작을 받으면 <span class="hl">수동태</span>이다. 수동태는 <span class="hl">be동사 + 과거분사(p.p.)</span>로 만들고, 동작을 한 사람은 <b>by + 목적격</b>으로 나타낸다. 행위자가 중요하지 않거나 누구인지 모를 때는 by ~를 생략한다.',
      table: { head: ['단계', '능동태 → 수동태', '예'], rows: [['1', '능동태의 목적어를 주어로', 'Tom cleaned the room. → The room ...'], ['2', '동사를 be + p.p.로 (시제·수 맞추기)', '→ The room was cleaned ...'], ['3', '능동태의 주어를 by + 목적격으로', '→ The room was cleaned by Tom.']], cap: '능동태를 수동태로 바꾸기' },
      ex: [["English is spoken in many countries.", "영어는 많은 나라에서 사용된다."], ["This song was written by my brother.", "이 노래는 우리 형에 의해 쓰였다."]] },
    { h: '시제에 따른 수동태와 과거분사',
      p: '수동태의 시제는 <b>be동사</b>로 나타낸다. 현재는 am/are/is, 과거는 was/were, 미래는 will be를 쓴다. 과거분사는 규칙 동사면 과거형과 같지만, 불규칙 동사는 따로 외워야 한다.',
      table: { head: ['시제', '형태', '예문'], rows: [['현재', 'am/are/is + p.p.', 'The store is opened at nine.'], ['과거', 'was/were + p.p.', 'The bridge was built in 2010.'], ['미래', 'will be + p.p.', 'The festival will be held next month.'], ['불규칙 p.p.', 'write – written, build – built, make – made, take – taken, speak – spoken, break – broken', '']] },
      warn: 'will be 뒤에도 과거분사를 쓴다. will be hold (×) → will be held (○)' },
    { h: '수동태의 부정문·의문문과 by 이외의 전치사',
      p: '부정문은 be동사 뒤에 not을 붙이고, 의문문은 be동사를 주어 앞으로 보낸다. 또 어떤 수동태 표현은 by 대신 다른 전치사를 쓰므로 함께 외워 둔다.',
      table: { head: ['표현', '뜻', '예문'], rows: [['be covered with', '~로 덮여 있다', 'The mountain is covered with snow.'], ['be filled with', '~로 가득 차 있다', 'The box was filled with toys.'], ['be interested in', '~에 관심이 있다', 'I am interested in science.'], ['be made of', '~로 만들어지다(재료가 보임)', 'This desk is made of wood.'], ['be known for', '~로 유명하다', 'Jeonju is known for bibimbap.']] },
      ex: [["The letter was not written in English.", "그 편지는 영어로 쓰이지 않았다."], ["Was the picture painted by her?", "그 그림은 그녀가 그렸니?"]] },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>This book ___ by many students.', o: ['reads', 'is read', 'is reading', 'read'], a: 1, why: '책은 "읽히는" 대상이고 by ~가 있으므로 수동태 is read를 쓴다.' },
    { lv: 1, q: 'write의 과거분사로 알맞은 것은?', o: ['wrote', 'writed', 'written', 'writing'], a: 2, why: 'write – wrote – written이다. wrote는 과거형이다.' },
    { lv: 1, q: '수동태의 기본 형태로 알맞은 것은?', o: ['be + 동사원형', 'have + p.p.', 'be + -ing', 'be + p.p.'], a: 3, why: '수동태는 be동사 + 과거분사(p.p.)로 만든다. be + -ing는 진행형이다.' },
    { lv: 2, q: '<b>Tom cleaned the room.</b>을 수동태로 바르게 바꾼 것은?', o: ['The room cleaned by Tom.', 'The room is cleaned by Tom.', 'The room was cleaned by Tom.', 'The room was cleaning by Tom.'], a: 2, why: '능동태가 과거(cleaned)이므로 was + p.p.를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>The mountain is covered ___ snow.', o: ['by', 'with', 'of', 'at'], a: 1, why: '"~로 덮여 있다"는 be covered with이다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>The bridge ___ in 2010.', o: ['was built', 'built', 'is built', 'was building'], a: 0, why: '다리는 "지어진" 대상이고 2010년은 과거이므로 was built이다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['English is spoken in many countries.', 'The window was broken by Sam.', 'The letter was sent yesterday.', 'The cake was made of my mom.'], a: 3, why: '케이크를 만든 사람(행위자)은 by로 나타내므로 by my mom이 맞다. be made of는 재료를 말할 때 쓴다.' },
    { lv: 3, q: '<b>Did she paint the picture?</b>를 수동태로 바르게 바꾼 것은?', o: ['Was the picture painted by her?', 'Did the picture painted by her?', 'Was the picture paint by her?', 'Is the picture painted by she?'], a: 0, why: '과거 수동태 의문문은 Was + 주어 + p.p. ~?이고, by 뒤에는 목적격 her를 쓴다.' },
    { lv: 3, q: '빈칸에 알맞은 말은?<br>The school festival ___ next month.', o: ['holds', 'will hold', 'will be held', 'was held'], a: 2, why: '축제는 "열리는" 대상이고 next month는 미래이므로 will be held이다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Hangeul, the Korean alphabet, (A) <span class="blank"></span> by King Sejong and his scholars in the 15th century. Before that, Korean people used Chinese characters, but they were too difficult for most people to learn. Hangeul is very scientific and easy to learn. Today, it (B) <span class="blank"></span> by millions of people around the world. October 9 is Hangeul Day, and it (C) <span class="blank"></span> every year in Korea.</div>`, o: ['created – is used – celebrates', 'was created – uses – is celebrated', 'was created – is used – is celebrated', 'is created – is used – is celebrated'], a: 2, why: '(A) 15세기에 "만들어졌다" → was created. (B) 오늘날 "사용된다" → is used. (C) 해마다 "기념된다" → is celebrated.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Our school has a beautiful garden. It <u>①&nbsp;was made</u> by students and teachers five years ago. Many kinds of flowers <u>②&nbsp;are grown</u> there. Every spring, the garden <u>③&nbsp;is visited</u> by many people from our town. Last year, a small pond <u>④&nbsp;added</u> to the garden, and now some fish live in it. The garden club members take care of it every day.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '연못은 정원에 "더해진" 것이므로 수동태 was added가 되어야 한다.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">The Blue Lake Bridge was built in 1985. It was designed by a young engineer named Ms. Kang. At that time, many people thought the bridge was too long and would not be safe. But it is still used by thousands of cars every day. In 2020, the bridge was painted blue, and it was given its new name. Now it is loved by tourists, especially at night when it is lit up.</div>`, o: ['다리는 1985년에 지어졌다.', '지금은 차가 다니지 않는다.', '다리는 젊은 기술자가 설계했다.', '2020년에 파란색으로 칠해졌다.'], a: 1, why: 'it is still used by thousands of cars every day라고 했으므로 지금도 차가 많이 다닌다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Plastic is everywhere in our lives. Every year, millions of tons of plastic (A) [make / are made]. Sadly, much of it (B) [is not recycled / does not recycle]. A lot of plastic ends up in the sea, and many sea animals (C) [hurt / are hurt] by it. We need to use less plastic to protect our planet. Each of us can help by carrying a reusable bag and a tumbler.</div>`, o: ['are made – is not recycled – are hurt', 'make – is not recycled – hurt', 'are made – does not recycle – are hurt', 'are made – is not recycled – hurt'], a: 0, why: '플라스틱은 "만들어지고", "재활용되지 않으며", 바다 동물은 플라스틱에 의해 "다친다". 모두 수동태가 필요하다.' },
    { lv: 5, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것을 찾아 바르게 고친 것은?<div class="passage">A strange box was found in our school's storage room last week. It <u>was covered</u> with dust. Inside the box, there were old photos and letters. They <u>were written</u> by students thirty years ago. The letters were for "future students." Our principal said the box <u>will show</u> at the school festival next month. Everyone is excited to see it.</div>`, o: ['was covered → covered', 'were written → wrote', 'will show → will be shown', 'will show → will shown'], a: 2, why: '상자는 축제에서 "보여질" 대상이므로 미래 수동태 will be shown이 맞다. was covered, were written은 이미 올바른 수동태이다.' },
    { lv: 5, q: `다음 글의 제목으로 가장 알맞은 것은?<div class="passage">Many great things were discovered by accident. For example, a scientist once left some dishes in his lab before a vacation. When he came back, he found that something in one dish stopped germs from growing. This led to an important medicine. Also, according to one story, a popular snack was made when a cook got angry and sliced potatoes very thin. Sometimes mistakes can be wonderful!</div>`, o: ['How to Clean a Lab', 'Great Discoveries Made by Accident', "Famous Scientists' Vacations", 'Why Germs Are Dangerous'], a: 1, why: '첫 문장이 주제문이고 약과 과자라는 두 예시로 우연한 발견을 설명한다.' },
  ],
});

ENG.add('m2', '현재완료', {
  sub: '과거의 일이 지금까지 이어질 때 have + p.p.',
  kw: ['현재완료', 'have/has + p.p.', '경험', '계속', '완료', '결과', 'for / since', 'have been to / have gone to'],
  sections: [
    { h: '현재완료의 형태',
      p: '현재완료는 <span class="hl">have/has + 과거분사(p.p.)</span>로, 과거에 일어난 일이 현재와 연결되어 있음을 나타낸다. 주어가 3인칭 단수이면 has를 쓴다.',
      table: { head: ['구분', '형태', '예문'], rows: [['긍정', 'have/has + p.p.', 'I have lived here for ten years.'], ['부정', "have/has not(haven't/hasn't) + p.p.", "She hasn't finished her homework yet."], ['의문', 'Have/Has + 주어 + p.p. ~?', 'Have you ever seen a whale?'], ['대답', 'Yes, I have. / No, I haven\'t.', '']] },
      ex: [["I have known him since 2020.", "나는 2020년부터 그를 알아 왔다."], ["Has he arrived yet? — Yes, he has.", "그는 이미 도착했니? — 응, 도착했어."]] },
    { h: '현재완료의 네 가지 용법',
      p: '현재완료는 함께 쓰인 표현을 보면 뜻을 구별하기 쉽다.',
      table: { head: ['용법', '뜻', '함께 쓰는 말', '예문'], rows: [['경험', '~한 적이 있다', 'ever, never, before, once, twice', 'I have visited Busan twice.'], ['계속', '(지금까지) 계속 ~해 왔다', 'for + 기간, since + 시점, How long', 'She has been sick since Monday.'], ['완료', '막 / 이미 ~했다', 'just, already, yet', 'He has already eaten lunch.'], ['결과', '~해 버렸다 (그래서 지금 ~하다)', 'have lost, have gone', 'I have lost my key.']], cap: '현재완료 용법 구별' },
      tip: 'for 뒤에는 기간(three years), since 뒤에는 시작 시점(2019, last Monday)이 온다.' },
    { h: '과거 시제와의 차이, have been to와 have gone to',
      p: '현재완료는 현재와 연결된 일을 나타내므로 <span class="hl">yesterday, last ~, ~ ago, When ~?</span>처럼 분명한 과거 시점을 나타내는 말과 함께 쓰지 않는다. 또 have been to는 "~에 가 본 적이 있다(경험)", have gone to는 "~에 가 버렸다(그래서 지금 여기 없다)"라는 뜻이다.',
      ex: [["We met him yesterday.", "우리는 어제 그를 만났다. (have met ×)"], ["I have been to Jeju twice.", "나는 제주에 두 번 가 본 적이 있다."], ["He has gone to London.", "그는 런던에 가 버렸다(지금 여기 없다)."]],
      warn: 'We have met him yesterday. (×) / When have you seen it? (×) → When did you see it? (○)' },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I ___ known him for five years.', o: ['has', 'have', 'am', 'did'], a: 1, why: '현재완료는 have/has + p.p.이고 주어가 I이므로 have를 쓴다.' },
    { lv: 1, q: 'see의 과거분사로 알맞은 것은?', o: ['seen', 'saw', 'seed', 'seeing'], a: 0, why: 'see – saw – seen이다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>She has lived here ___ 2020.', o: ['for', 'ago', 'since', 'before'], a: 2, why: '2020은 시작 시점이므로 since를 쓴다. for 뒤에는 기간이 온다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>Have you ever ___ to Jeju Island?', o: ['go', 'went', 'being', 'been'], a: 3, why: '"~에 가 본 적이 있니?"는 Have you ever been to ~?로 묻는다.' },
    { lv: 2, q: '우리말과 뜻이 같은 문장은?<br>나는 아직 숙제를 끝내지 못했다.', o: ["I haven't finished my homework already.", "I haven't finished my homework yet.", "I don't finish my homework yet.", "I haven't finish my homework yet."], a: 1, why: '부정문에서 "아직"은 yet이다. haven\'t 뒤에는 과거분사 finished를 쓴다.' },
    { lv: 2, q: '밑줄 친 현재완료의 용법은?<br>I have <u>visited</u> Busan twice.', o: ['경험', '계속', '완료', '결과'], a: 0, why: 'twice(두 번)와 함께 "방문한 적이 있다"라는 경험을 나타낸다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I have seen the movie before.', 'He has just arrived.', 'We have met him yesterday.', 'They have been friends since 2019.'], a: 2, why: 'yesterday는 분명한 과거 시점이므로 현재완료와 함께 쓸 수 없다. We met him yesterday.가 맞다.' },
    { lv: 3, q: '현재완료의 용법이 나머지 셋과 <b>다른</b> 것은?', o: ['I have lived here for ten years.', 'She has been sick since Monday.', 'We have known each other for a long time.', 'He has already eaten lunch.'], a: 3, why: '④는 already와 함께 쓰인 완료 용법이고, 나머지는 for / since가 있는 계속 용법이다.' },
    { lv: 3, q: '<b>He has gone to London.</b>의 뜻으로 알맞은 것은?', o: ['그는 런던에 가 본 적이 있다.', '그는 런던에 가 버렸다(그래서 지금 여기 없다).', '그는 런던에 갈 것이다.', '그는 런던에서 돌아왔다.'], a: 1, why: 'have gone to는 결과 용법으로 "가 버려서 지금 여기 없다"는 뜻이다. "가 본 적이 있다"는 has been to이다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">My family moved to Daegu three years ago. Since then, I (A) <span class="blank"></span> at Hanbit Middle School. At first, I missed my old friends a lot. But now I (B) <span class="blank"></span> many new friends here. My best friend is Jiwoo. We (C) <span class="blank"></span> each other since the first day of school. Last summer, we went to a music festival together. It was my best memory in Daegu.</div>`, o: ['studied – made – knew', 'have studied – have made – have known', 'have studied – made – have known', 'have studied – have made – knew'], a: 1, why: '(A) Since then으로 지금까지 계속 → have studied. (B) now와 연결된 결과 → have made. (C) since ~ → have known.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Have you ever <u>①&nbsp;heard</u> of the "five-second rule"? Some people believe food is safe if you pick it up within five seconds. I <u>②&nbsp;have believed</u> this rule since I was little. But last week, I <u>③&nbsp;have read</u> an article about it. Scientists <u>④&nbsp;have found</u> that germs can get on food in less than one second. Now I don't eat food that falls on the floor.</div>`, o: ['①', '②', '③', '④'], a: 2, why: 'last week는 분명한 과거 시점이므로 과거형 read를 써야 한다.' },
    { lv: 4, q: `다음 대화의 내용과 일치하는 것은?<div class="passage">A: Hi, Mina. Have you finished the science report?<br>B: Not yet. I've just started it.<br>A: Really? It's due tomorrow.<br>B: I know. I've been busy with the school play for two weeks.<br>A: Oh, I see. Do you need any help? I've already finished mine.<br>B: Thanks! Can you help me find some pictures?</div>`, o: ['미나는 2주 동안 연극 때문에 바빴다.', '미나는 보고서를 이미 끝냈다.', 'A는 아직 보고서를 시작하지 않았다.', '보고서는 다음 주까지이다.'], a: 0, why: "I've been busy with the school play for two weeks.라고 했다. 미나는 막 시작했고, A는 이미 끝냈으며, 마감은 내일이다." },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Seoyeon is a member of the school volunteer club. She (A) [joined / has joined] the club two years ago. Since then, she (B) [visited / has visited] the nursing home in her town every month. She reads books to the elderly and talks with them. "They (C) [became / have become] like my grandparents since I first met them," she says. Next month, she will start teaching them how to use smartphones.</div>`, o: ['has joined – visited – became', 'joined – has visited – have become', 'joined – visited – have become', 'joined – has visited – became'], a: 1, why: '(A) two years ago는 과거 시점 → joined. (B) Since then 이후 계속 → has visited. (C) since 절과 함께 → have become.' },
    { lv: 5, q: `다음 글을 읽고 답할 수 <b>없는</b> 질문은?<div class="passage">I have been to three countries so far: Japan, Vietnam, and Australia. Japan was the first. I went there with my parents when I was ten. Australia was the most exciting. I saw kangaroos and swam in the ocean. I have never been to Europe, but I hope to visit France someday. I have studied French for a year to prepare for the trip.</div>`, o: ['When did the writer go to Australia?', 'How many countries has the writer been to?', 'Which country did the writer visit first?', 'How long has the writer studied French?'], a: 0, why: '호주에 간 시기는 나오지 않는다. 방문한 나라 수(3개), 첫 방문국(일본), 프랑스어 공부 기간(1년)은 알 수 있다.' },
    { lv: 5, q: `밑줄 친 부분과 현재완료의 용법이 같은 것은?<div class="passage">My little brother, Doyun, is crying in his room. He <u>has lost</u> his favorite toy car, so he can't play with it now. He took it to the playground this morning. He thinks he left it on the slide. My mom and I have looked for it everywhere, but we haven't found it yet. If we can't find it, I am going to buy him a new one with my allowance.</div>`, o: ['I have been to Canada once.', 'She has gone to Paris.', 'We have lived here for a long time.', 'They have just finished dinner.'], a: 1, why: 'has lost는 "잃어버려서 지금 없다"는 결과 용법이다. has gone to(가 버려서 지금 없다)도 결과 용법이다. ①은 경험, ③은 계속, ④는 완료이다.' },
  ],
});

ENG.add('m2', '비교급과 최상급', {
  sub: '원급·비교급·최상급의 여러 표현',
  kw: ['비교급', '최상급', 'as ~ as', '배수 비교', '비교급 강조', 'the 비교급, the 비교급', 'one of the 최상급', '불규칙 비교'],
  sections: [
    { h: '비교급·최상급 만드는 법',
      p: '대부분의 형용사·부사는 <span class="hl">-er / -est</span>를 붙여 비교급과 최상급을 만들고, 3음절 이상이거나 -ful, -ous, -ing 등으로 끝나는 긴 단어는 <span class="hl">more / most</span>를 앞에 쓴다. 몇몇 단어는 불규칙하게 변한다.',
      table: { head: ['규칙', '원급', '비교급', '최상급'], rows: [['+er / +est', 'tall, fast', 'taller, faster', 'tallest, fastest'], ['자음 + y', 'easy, happy', 'easier, happier', 'easiest, happiest'], ['단모음 + 단자음', 'hot, big', 'hotter, bigger', 'hottest, biggest'], ['more / most', 'famous, interesting', 'more famous, more interesting', 'most famous, most interesting'], ['불규칙', 'good / well', 'better', 'best'], ['불규칙', 'bad', 'worse', 'worst'], ['불규칙', 'many / much', 'more', 'most'], ['불규칙', 'little', 'less', 'least']], cap: '비교급·최상급 변화표' },
      ex: [["Today is hotter than yesterday.", "오늘은 어제보다 덥다."], ["This is the most interesting book of all.", "이것이 모든 책 중에서 가장 재미있는 책이다."]] },
    { h: '원급 비교와 배수 표현',
      p: '<span class="hl">as + 원급 + as</span>는 "~만큼 …한", <span class="hl">not as(so) + 원급 + as</span>는 "~만큼 …하지 않은"이라는 뜻이다. as 앞에 twice, three times를 쓰면 "~보다 몇 배 …한"이 된다.',
      ex: [["Tom is not as tall as his brother.", "톰은 형만큼 키가 크지 않다."], ["This room is twice as big as mine.", "이 방은 내 방보다 두 배 크다."], ["His phone is three times as expensive as mine.", "그의 휴대폰은 내 것보다 세 배 비싸다."]],
      warn: 'as 사이에는 원급을 쓴다. as taller as (×)' },
    { h: '비교급 강조와 비교급 관용 표현',
      p: '비교급을 강조할 때는 <span class="hl">much, even, far, a lot</span>을 쓰고 "훨씬"으로 해석한다. very는 비교급을 꾸미지 못한다. <b>비교급 and 비교급</b>은 "점점 더 ~한", <b>the 비교급 ~, the 비교급 …</b>은 "~할수록 더 …하다"이다.',
      ex: [["She is much taller than me.", "그녀는 나보다 훨씬 키가 크다."], ["It is getting colder and colder.", "날씨가 점점 더 추워지고 있다."], ["The more you read, the more you learn.", "많이 읽을수록 더 많이 배운다."]],
      warn: 'very taller (×) → much taller (○)' },
    { h: '최상급의 여러 표현',
      p: '최상급 뒤에는 범위를 나타내는 <b>in + 장소·집단</b>이나 <b>of + 복수 명사</b>가 자주 온다. <span class="hl">one of the + 최상급 + 복수 명사</span>는 "가장 ~한 것 중 하나"이다. 원급·비교급으로도 최상급의 뜻을 나타낼 수 있다.',
      table: { head: ['형태', '예문'], rows: [['the + 최상급', 'Sumi is the smartest student in her class.'], ['비교급 + than any other + 단수 명사', 'Sumi is smarter than any other student in her class.'], ['비교급 + than all the other + 복수 명사', 'Sumi is smarter than all the other students in her class.'], ['No (other) + 명사 ~ 비교급 + than', 'No student in her class is smarter than Sumi.']], cap: '같은 뜻의 최상급 표현' },
      ex: [["He is one of the best players in our school.", "그는 우리 학교에서 가장 뛰어난 선수 중 한 명이다."]] },
  ],
  bank: [
    { lv: 1, q: 'good의 비교급으로 알맞은 것은?', o: ['gooder', 'better', 'best', 'more good'], a: 1, why: 'good은 불규칙 변화로 good – better – best이다.' },
    { lv: 1, q: 'hot의 최상급으로 알맞은 것은?', o: ['hotest', 'most hot', 'hoter', 'hottest'], a: 3, why: 'hot은 단모음 + 단자음이므로 t를 한 번 더 쓰고 -est를 붙인다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>This is ___ book of all.', o: ['interesting', 'more interesting', 'the most interesting', 'most interestinger'], a: 2, why: 'of all(모든 것 중에서)이 있으므로 최상급이고, interesting은 긴 단어라 the most를 쓴다.' },
    { lv: 2, q: '비교급을 강조하는 말로 쓸 수 <b>없는</b> 것은?', o: ['very', 'much', 'even', 'far'], a: 0, why: 'very는 원급을 꾸미고 비교급은 꾸미지 못한다. much, even, far, a lot은 비교급을 강조한다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>Tom is not as ___ as his brother.', o: ['taller', 'tall', 'tallest', 'more tall'], a: 1, why: 'as ~ as 사이에는 원급을 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>He is one of the best ___ in our school.', o: ['player', 'players', 'playing', 'to play'], a: 1, why: 'one of the + 최상급 뒤에는 복수 명사가 온다.' },
    { lv: 3, q: '<b>Sumi is the smartest student in her class.</b>와 뜻이 <b>다른</b> 것은?', o: ['Sumi is smarter than any other student in her class.', 'No student in her class is smarter than Sumi.', 'Sumi is smarter than all the other students in her class.', 'Sumi is as smart as the other students in her class.'], a: 3, why: '④는 "다른 학생들만큼 똑똑하다"는 뜻으로, 가장 똑똑하다는 뜻이 아니다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['This room is twice as big as mine.', 'It is getting colder and colder.', 'She is very taller than me.', 'The more you read, the more you learn.'], a: 2, why: 'very는 비교급을 강조할 수 없다. much(even, far) taller로 고쳐야 한다.' },
    { lv: 3, q: '빈칸에 알맞은 말은?<br>The ___ you practice, the better you will play.', o: ['much', 'more', 'many', 'most'], a: 1, why: '"~할수록 더 …하다"는 the 비교급, the 비교급이다. 앞에도 비교급 more가 필요하다.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Three friends compared their smartphones. Jun's phone is two years old, Yena's phone is four years old, and Theo's phone is brand new. Yena's phone is the oldest, but its battery lasts longer than Jun's. Theo's phone is the most expensive of the three. It is three times as expensive as Jun's phone. But Jun thinks his phone is the best because it is the lightest.</div>`, o: ['예나의 휴대폰이 가장 오래되었다.', '예나의 휴대폰 배터리가 준의 것보다 오래간다.', '테오의 휴대폰이 가장 비싸다.', '준의 휴대폰이 가장 무겁다.'], a: 3, why: 'it is the lightest라고 했으므로 준의 휴대폰은 가장 가볍다.' },
    { lv: 4, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Which pet is (A) [better / best] for you, a dog or a cat? Dogs usually need (B) [more / most] attention than cats. You have to walk them every day and play with them a lot. Cats are (C) [very / much] more independent. They can stay alone longer. If you are busy, a cat may be a better choice. But if you love outdoor activities, a dog will be a great friend.</div>`, o: ['best – more – much', 'better – most – very', 'better – more – much', 'better – more – very'], a: 2, why: '(A) 둘 중 하나를 고르므로 비교급 better. (B) than이 있으므로 more. (C) 비교급 more independent를 강조하므로 much.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Mt. Halla is <u>①&nbsp;the highest</u> mountain in South Korea. It is <u>②&nbsp;much high</u> than Mt. Jiri. Climbing it takes <u>③&nbsp;longer</u> than most people think, so you should start early in the morning. But when you reach the top, you can see Baengnokdam, a lake inside the crater. It was <u>④&nbsp;the most beautiful</u> sight I have ever seen.</div>`, o: ['①', '②', '③', '④'], a: 1, why: 'than이 있으므로 비교급이 필요하다. much higher로 고쳐야 한다. much는 비교급을 강조하는 말이다.' },
    { lv: 5, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Our class did a survey about favorite subjects. Twelve students chose P.E., eight chose music, and six chose science. Only four students chose math. P.E. was the most popular subject, and our teacher was not surprised at all. Interestingly, music was twice as popular as math. Our teacher said she would use the results to plan more fun activities for the class.</div>`, o: ['Science was more popular than music.', 'Math was the least popular subject.', 'Music was as popular as P.E.', 'P.E. was three times as popular as science.'], a: 1, why: '수학은 4명으로 가장 적게 선택되었다. 체육(12명)은 과학(6명)의 두 배이지 세 배가 아니다.' },
    { lv: 5, q: `빈칸에 들어갈 말로 가장 알맞은 것은?<div class="passage">Learning a musical instrument is not easy at first. Your fingers hurt, and the sounds are not pretty. Many people give up after a few weeks. But don't give up. Practice a little every day. <span class="blank"></span>, the better you will become. Soon you will be able to play your favorite songs. Then playing music will be more fun than anything else.</div>`, o: ['The most you practice', 'More you practice', 'The much you practice', 'The more you practice'], a: 3, why: '뒤에 the better가 이어지므로 "the 비교급, the 비교급" 구문이 되도록 The more you practice를 쓴다.' },
    { lv: 5, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">Many people think a bigger house is always better. But a big house has some problems. It costs more money to heat in winter. It takes much longer to clean. Recently, more and more people are choosing smaller homes. They say small homes are cheaper, easier to take care of, and even cozier. For them, a simpler life is a happier life.</div>`, o: ['큰 집이 언제나 더 좋다.', '겨울에는 난방비가 많이 든다.', '작은 집에도 장점이 많다.', '청소는 매일 해야 한다.'], a: 2, why: 'But 이후 큰 집의 단점과 작은 집의 장점을 들어 작은 집도 좋다는 요지를 전한다. ①은 글쓴이가 반박하는 생각이다.' },
  ],
});

ENG.add('m2', '접속사 when·because·if·that', {
  sub: '시간·이유·조건·명사절을 잇는 접속사',
  kw: ['접속사', 'when / while', 'because / because of', 'if / unless', 'that', '시간·조건 부사절', '명사절', 'so'],
  sections: [
    { h: '시간과 조건의 접속사',
      p: 'when(~할 때), before(~하기 전에), after(~한 후에), while(~하는 동안)은 시간을, if(만약 ~하면), unless(~하지 않으면)는 조건을 나타낸다. <span class="hl">시간·조건의 부사절에서는 미래의 일이라도 현재 시제</span>를 쓴다.',
      table: { head: ['종류', '접속사', '예문'], rows: [['시간', 'when, before, after, while', 'I will call you when I arrive.'], ['조건', 'if, unless(= if ~ not)', 'If it rains tomorrow, we will stay home.'], ['이유', 'because, since', 'I stayed home because I was sick.'], ['명사절', 'that', 'I think that he is honest.'], ['결과', 'so', 'I was tired, so I went to bed early.']], cap: '주요 접속사 정리' },
      ex: [["While I was sleeping, it snowed a lot.", "내가 자는 동안 눈이 많이 왔다."], ["Unless you hurry, you will miss the bus.", "서두르지 않으면 버스를 놓칠 것이다."]],
      warn: 'If it will rain tomorrow (×) → If it rains tomorrow (○)' },
    { h: '이유와 결과: because, because of, so',
      p: '<span class="hl">because</span> 뒤에는 주어 + 동사가 있는 <b>절</b>이 오고, <span class="hl">because of</span> 뒤에는 <b>명사(구)</b>가 온다. so는 "그래서"라는 뜻으로 결과를 나타내며, 이유와 결과의 순서가 because와 반대이다.',
      ex: [["I was late because the traffic was heavy.", "차가 많이 막혀서 나는 늦었다."], ["I was late because of the heavy traffic.", "심한 교통 체증 때문에 나는 늦었다."], ["The traffic was heavy, so I was late.", "차가 많이 막혀서 나는 늦었다."]],
      tip: 'because 뒤에 동사가 보이면 절, 동사 없이 명사만 있으면 because of이다.' },
    { h: '명사절을 이끄는 that',
      p: '접속사 that은 "~라는 것"이라는 뜻으로 문장 전체를 명사처럼 만든다. think, believe, know, say, hope 등의 목적어로 쓰일 때는 <span class="hl">that을 생략</span>할 수 있다. that절이 주어일 때는 보통 가주어 it을 쓰고 that절을 뒤로 보낸다.',
      ex: [["I know (that) you are right.", "나는 네가 옳다는 것을 안다."], ["It is true that he won the prize.", "그가 상을 받았다는 것은 사실이다."]],
      warn: '"저 ~"라는 뜻의 지시형용사 that(that girl)이나 지시대명사 that(That is my bag)과 구별한다.' },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 접속사는?<br>___ I was young, I lived in Jeju.', o: ['When', 'Because', 'If', 'That'], a: 0, why: '"내가 어렸을 때"라는 시간을 나타내므로 When을 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 말은?<br>I was late ___ the heavy traffic.', o: ['because', 'because of', 'if', 'that'], a: 1, why: '뒤에 명사구(the heavy traffic)만 있으므로 because of를 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 접속사는?<br>I think ___ he is honest.', o: ['if', 'because', 'when', 'that'], a: 3, why: 'think의 목적어가 되는 명사절을 이끄는 that이 알맞다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>If it ___ tomorrow, we will stay home.', o: ['will rain', 'rains', 'rained', 'rain'], a: 1, why: '조건의 부사절에서는 미래의 일도 현재 시제로 쓴다. 주어 it이 3인칭 단수라서 rains이다.' },
    { lv: 2, q: '두 문장의 뜻이 같도록 빈칸에 알맞은 말은?<br>It was cold. So I wore a coat.<br>= I wore a coat ___ it was cold.', o: ['if', 'that', 'because', 'unless'], a: 2, why: '추웠던 것이 코트를 입은 이유이므로 because를 쓴다.' },
    { lv: 2, q: '밑줄 친 that을 생략할 수 있는 것은?', o: ['I know <u>that</u> you are right.', '<u>That</u> book is mine.', 'I like <u>that</u> song.', '<u>That</u> is my bag.'], a: 0, why: '①의 that은 know의 목적어인 명사절을 이끄는 접속사라서 생략할 수 있다. 나머지는 "저"라는 뜻의 지시어이다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I will call you when I arrive.', 'If you will hurry, you will catch the bus.', 'She was happy because she passed the test.', 'I believe that you can do it.'], a: 1, why: '조건 부사절에서는 현재 시제를 쓰므로 If you hurry가 맞다.' },
    { lv: 3, q: '문맥상 빈칸에 가장 알맞은 말은?<br>___ you study hard, you won\'t pass the test.', o: ['If', 'Unless', 'Because', 'That'], a: 1, why: '"열심히 공부하지 않으면 시험에 통과하지 못할 것이다"라는 뜻이 되어야 하므로 Unless(= If ~ not)가 알맞다.' },
    { lv: 3, q: '밑줄 친 that의 쓰임이 나머지 셋과 <b>다른</b> 것은?', o: ['I hope <u>that</u> you feel better.', 'He said <u>that</u> he was busy.', 'Do you know <u>that</u> girl?', 'I think <u>that</u> it is true.'], a: 2, why: '③은 "저 소녀"라는 뜻의 지시형용사이고, 나머지는 명사절을 이끄는 접속사이다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Last Friday, I was very tired (A) <span class="blank"></span> I studied until late the night before. In class, I fell asleep (B) <span class="blank"></span> the teacher was talking. After class, my teacher said to me, "If you (C) <span class="blank"></span> more sleep, you will feel better and learn more." Since then, I have gone to bed before eleven. Now I feel much more energetic during the day.</div>`, o: ['because – while – will get', 'if – while – get', 'because – that – get', 'because – while – get'], a: 3, why: '(A) 피곤한 이유 → because. (B) 선생님이 말씀하시는 동안 → while. (C) 조건 부사절은 현재 시제 → get.' },
    { lv: 4, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">When Hana was ten, she found a hurt bird in her yard. She took care of it because she couldn't leave it alone. She gave it water and some seeds every day. After a week, the bird was able to fly again. Hana felt sad when it flew away, but she was also proud. She learned that small acts of kindness can save a life. Now she wants to be a vet.</div>`, o: ['하나는 열 살 때 다친 새를 발견했다.', '하나는 새에게 물과 씨앗을 주었다.', '새는 한 달 뒤에 다시 날 수 있었다.', '하나는 지금 수의사가 되고 싶어 한다.'], a: 2, why: 'After a week라고 했으므로 새는 일주일 뒤에 다시 날 수 있었다.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Many people believe <u>①&nbsp;that</u> eating late at night is bad for you. <u>②&nbsp;When</u> you eat right before bed, your body can't rest well. <u>③&nbsp;Because of</u> your stomach is still working, you may not sleep deeply. <u>④&nbsp;If</u> you feel hungry at night, try a glass of warm milk or a banana instead of a big meal.</div>`, o: ['①', '②', '③', '④'], a: 2, why: '뒤에 주어(your stomach)와 동사(is working)가 있는 절이 오므로 Because를 써야 한다.' },
    { lv: 5, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Do you get nervous (A) <span class="blank"></span> you speak in front of people? Many people do. Experts say (B) <span class="blank"></span> this is completely natural. Your heart beats faster (C) <span class="blank"></span> your body is getting ready for action. Here's a tip: if you practice your speech many times, you will feel more confident. Also, try to look at friendly faces in the audience.</div>`, o: ['if – that – because of', 'when – that – because', 'when – if – because', 'when – because – that'], a: 1, why: '(A) 사람들 앞에서 말할 때 → when. (B) say의 목적어 명사절 → that. (C) 뒤에 절이 오고 심장이 빨리 뛰는 이유 → because.' },
    { lv: 5, q: `빈칸에 들어갈 말로 가장 알맞은 것은?<div class="passage">Jinu wanted to buy a new bike, but it was too expensive. His dad said, "If you save some money every week, I will pay the rest." Jinu agreed. He stopped buying snacks and saved his allowance. After three months, he had enough money for half of the bike. His dad kept his promise, and Jinu finally got the bike. Jinu learned that <span class="blank"></span>.</div>`, o: ['bikes are cheaper in winter', "his dad didn't like bikes", 'snacks are good for health', 'saving money takes patience, but it pays off'], a: 3, why: '석 달 동안 간식을 줄이며 돈을 모아 결국 자전거를 얻었으므로, 저축은 인내가 필요하지만 보람이 있다는 교훈이 알맞다.' },
    { lv: 5, q: `다음 글의 요지로 가장 알맞은 것은?<div class="passage">Some people think that they must be perfect. When they make a mistake, they feel terrible. But mistakes are not always bad. If you never make mistakes, you probably aren't trying anything new. Scientists and artists make many mistakes before they succeed. So don't be afraid of mistakes. They are a part of learning.</div>`, o: ['과학자는 예술가보다 실수를 더 많이 한다.', '완벽한 사람만 성공할 수 있다.', '실수는 배움의 일부이므로 두려워하지 말라.', '새로운 것을 시도하지 말라.'], a: 2, why: 'But 뒤에서 실수가 나쁘지만은 않다고 하고, 마지막 So 문장에서 실수를 두려워하지 말라고 정리한다.' },
  ],
});

ENG.add('m2', '관계대명사 기초', {
  sub: 'who·which·that·whose로 명사 꾸미기',
  kw: ['관계대명사', '선행사', 'who', 'which', 'that', 'whose', '주격', '목적격 생략'],
  sections: [
    { h: '관계대명사의 역할과 종류',
      p: '관계대명사는 두 문장을 이어 주면서 앞의 명사(<span class="hl">선행사</span>)를 꾸미는 절을 이끈다. 선행사가 사람인지 사물·동물인지, 관계대명사가 절 안에서 주어인지 목적어인지 소유격인지에 따라 알맞은 것을 고른다.',
      table: { head: ['선행사', '주격', '목적격', '소유격'], rows: [['사람', 'who / that', 'who(m) / that', 'whose'], ['사물·동물', 'which / that', 'which / that', 'whose'], ['사람·사물 모두', 'that', 'that', '-']], cap: '관계대명사의 종류' },
      ex: [["I have a friend who lives in Canada.", "나는 캐나다에 사는 친구가 있다."], ["This is the bag which I bought yesterday.", "이것은 내가 어제 산 가방이다."]] },
    { h: '주격 관계대명사',
      p: '관계대명사가 절 안에서 주어 역할을 하면 주격이다. 주격 관계대명사 뒤에는 바로 <b>동사</b>가 오며, 그 동사는 <span class="hl">선행사의 수</span>에 맞춘다.',
      ex: [["The boy who lives next door is my classmate.", "옆집에 사는 소년은 나의 반 친구이다."], ["The boys who are playing soccer are my classmates.", "축구를 하고 있는 소년들은 나의 반 친구들이다."], ["I have a dog which runs very fast.", "나는 아주 빨리 달리는 개가 있다."]],
      warn: 'The people who lives next door (×) → The people who live next door (○)' },
    { h: '목적격 관계대명사와 소유격 whose',
      p: '관계대명사가 절 안에서 목적어 역할을 하면 목적격이며, <span class="hl">생략할 수 있다</span>. 관계대명사가 이미 목적어 역할을 하므로 절 안에 목적어(it, him 등)를 또 쓰면 안 된다. <b>whose</b>는 "~의"라는 뜻으로 뒤에 명사가 바로 온다.',
      ex: [["This is the cake (that) my mom made.", "이것은 엄마가 만드신 케이크이다."], ["I met a boy whose name was Leo.", "나는 이름이 레오인 소년을 만났다."], ["I saw a cat whose tail was very long.", "나는 꼬리가 아주 긴 고양이를 보았다."]],
      warn: 'This is the movie that I watched it. (×) → that I watched (○)' },
  ],
  bank: [
    { lv: 1, q: '빈칸에 알맞은 관계대명사는?<br>I have a friend ___ lives in Canada.', o: ['which', 'who', 'whose', 'what'], a: 1, why: '선행사가 사람(a friend)이고 뒤에 동사 lives가 오는 주격이므로 who를 쓴다.' },
    { lv: 1, q: '빈칸에 알맞은 관계대명사는?<br>This is the bag ___ I bought yesterday.', o: ['who', 'whose', 'which', 'where'], a: 2, why: '선행사가 사물(the bag)이고 bought의 목적어 역할을 하므로 which를 쓴다.' },
    { lv: 1, q: '선행사가 사람이든 사물이든 쓸 수 있는 관계대명사는?', o: ['that', 'who', 'which', 'whom'], a: 0, why: 'that은 사람과 사물에 모두 쓸 수 있다. who, whom은 사람, which는 사물에 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 관계대명사는?<br>I know a girl ___ father is a pilot.', o: ['who', 'whose', 'which', 'that'], a: 1, why: '"그 소녀의 아버지"라는 소유 관계이고 뒤에 명사 father가 오므로 whose를 쓴다.' },
    { lv: 2, q: '빈칸에 알맞은 말은?<br>The boys who ___ soccer over there are my classmates.', o: ['plays', 'is playing', 'are playing', 'was playing'], a: 2, why: '주격 관계대명사 뒤의 동사는 선행사(The boys, 복수)에 수를 맞춘다.' },
    { lv: 2, q: '밑줄 친 관계대명사를 생략할 수 있는 것은?', o: ['The man <u>who</u> helped me was kind.', 'I have a dog <u>which</u> runs fast.', 'She is the girl <u>who</u> won the race.', 'This is the cake <u>that</u> my mom made.'], a: 3, why: '④의 that은 made의 목적어 역할을 하는 목적격이라 생략할 수 있다. 나머지는 주격이다.' },
    { lv: 3, q: '두 문장을 한 문장으로 바르게 연결한 것은?<br>I met a boy. His name was Leo.', o: ['I met a boy who name was Leo.', 'I met a boy whose name was Leo.', 'I met a boy which name was Leo.', 'I met a boy that his name was Leo.'], a: 1, why: 'His(소유격)를 대신하므로 소유격 관계대명사 whose를 쓴다.' },
    { lv: 3, q: '다음 중 어법상 <b>틀린</b> 문장은?', o: ['I saw a cat which tail was very long.', 'The book which is on the desk is mine.', 'He is the singer who I like most.', 'The woman that teaches us is kind.'], a: 0, why: '"고양이의 꼬리"이므로 소유격 whose를 써야 한다. a cat whose tail was very long.' },
    { lv: 3, q: '다음 중 어법상 올바른 문장은?', o: ['This is the movie that I watched it.', 'The people who lives next door are nice.', 'I like the boy which sits next to me.', 'The pen which I lost was blue.'], a: 3, why: '① it을 빼야 하고, ② 선행사가 복수라서 live, ③ 선행사가 사람이라 who(that)를 써야 한다.' },
    { lv: 4, q: `빈칸 (A), (B), (C)에 들어갈 말로 알맞은 것은?<div class="passage">Have you heard of Kim Minji? She is a teenager (A) <span class="blank"></span> started a small project to help animals. She collects old towels and blankets (B) <span class="blank"></span> people don't use anymore. Then she takes them to an animal shelter near her town. She also visits a shelter (C) <span class="blank"></span> owner is her neighbor. Many people who heard about her project have joined her.</div>`, o: ['which – that – whose', 'who – which – whose', 'who – which – who', 'who – who – whose'], a: 1, why: '(A) 선행사가 사람이고 주격 → who. (B) 선행사가 사물이고 목적격 → which. (C) "보호소의 주인" 소유 관계 → whose.' },
    { lv: 4, q: `밑줄 친 부분 중 어법상 <b>틀린</b> 것은?<div class="passage">Last weekend, I went to a bookstore <u>①&nbsp;which</u> opened near my school. I found a book <u>②&nbsp;that</u> has many beautiful pictures of space. The man <u>③&nbsp;who</u> works at the store recommended another book. It was written by a scientist <u>④&nbsp;which</u> studies stars. I bought both books, and I've already finished one of them.</div>`, o: ['①', '②', '③', '④'], a: 3, why: '선행사 a scientist가 사람이므로 who(that)를 써야 한다.' },
    { lv: 4, q: `다음 글이 설명하는 사람으로 알맞은 것은?<div class="passage">This is a person who works on a plane. This person serves food and drinks that passengers order. This person also helps people who feel sick during the flight. Most of all, this person keeps passengers safe in an emergency. People who want this job need to speak foreign languages well and be kind to others.</div>`, o: ['a flight attendant', 'a pilot', 'a doctor', 'a tour guide'], a: 0, why: '비행기에서 음식을 나르고, 아픈 승객을 돕고, 비상시 승객을 지키는 사람은 승무원이다. 조종사는 음식을 나르지 않는다.' },
    { lv: 5, q: `(A), (B), (C)의 각 네모 안에서 어법에 맞는 말로 바르게 짝지은 것은?<div class="passage">Do you have a friend (A) [who / which] always listens to you? A true friend is someone (B) [who / whose] you can trust. Friends (C) [who care / who cares] about you will tell you the truth, even when it is hard to hear. It's not about how many friends you have. One friend that understands you is better than ten friends who don't.</div>`, o: ['which – who – who care', 'who – whose – who cares', 'who – who – who care', 'who – who – who cares'], a: 2, why: '(A) 선행사가 사람 → who. (B) trust의 목적어 역할, 뒤에 명사 없음 → who. (C) 선행사 Friends가 복수 → care.' },
    { lv: 5, q: `밑줄 친 that 중 관계대명사로 쓰인 것끼리 짝지은 것은?<div class="passage">My grandfather has a watch <u>ⓐ&nbsp;that</u> is over fifty years old. He says <u>ⓑ&nbsp;that</u> his father gave it to him. The watch <u>ⓒ&nbsp;that</u> he wears every day still works perfectly. He told me <u>ⓓ&nbsp;that</u> he would give it to me someday. I hope that day comes late, because I want him to wear it for a long time.</div>`, o: ['ⓐ, ⓑ', 'ⓐ, ⓒ', 'ⓑ, ⓓ', 'ⓒ, ⓓ'], a: 1, why: 'ⓐ는 a watch를 꾸미는 주격, ⓒ는 The watch를 꾸미는 목적격 관계대명사이다. ⓑ, ⓓ는 says, told의 목적어인 명사절을 이끄는 접속사이다.' },
    { lv: 5, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Jeonghun is a boy who loves building things. He has a small workshop that his father made in the garage. Last year, he made a birdhouse which now hangs on the tree in front of his house. Birds that come to it make him happy. This year, he wants to make a desk for his younger sister, whose old desk is broken.</div>`, o: ['정훈이는 무언가를 만드는 것을 좋아한다.', '작업실은 아버지가 차고에 만들어 주셨다.', '올해는 여동생의 책상을 만들 계획이다.', '새집은 정훈이의 방 안에 걸려 있다.'], a: 3, why: '새집은 집 앞 나무에 걸려 있다(hangs on the tree in front of his house).' },
  ],
});

ENG.add('m2', '독해: 세부 내용과 내용 일치', {
  sub: '선택지 먼저, 핵심어로 본문과 대조하기',
  kw: ['내용 일치', '내용 불일치', '세부 정보', '안내문', '핵심어', '숫자·날짜', '극단 표현', 'only / never / all'],
  sections: [
    { h: '세부 내용 문제의 종류',
      p: '세부 내용 문제는 글의 중심 생각보다 <b>구체적인 정보</b>를 정확히 읽었는지 묻는다. "글의 내용과 일치하는(않는) 것", "글을 읽고 답할 수 없는 질문", 안내문의 내용 확인 등이 있다. 정답은 반드시 <span class="hl">본문에 근거</span>가 있어야 하며, 상식으로 판단하면 안 된다.',
      ex: [["The museum is closed on Mondays.", "박물관은 월요일마다 휴관한다. (요일 정보)"], ["Only twenty students can join.", "오직 20명의 학생만 참가할 수 있다. (숫자·제한 정보)"]],
      tip: '선택지는 대부분 본문 순서대로 나온다. ①을 확인한 곳 다음부터 ②를 찾으면 빠르다.' },
    { h: '내용 일치 풀이 순서',
      p: '본문을 먼저 다 해석하고 선택지를 보면 다시 본문을 읽어야 한다. 선택지를 먼저 보고 무엇을 확인할지 정한 다음 본문을 읽는다.',
      table: { head: ['순서', '할 일', '예'], rows: [['1', '발문 확인: 일치인지 불일치인지 표시', '"일치하지 않는" → ✕ 표시'], ['2', '선택지의 핵심어 표시', '숫자, 날짜, 요일, 이름, 장소'], ['3', '본문에서 핵심어가 나오는 문장 찾기', 'July 22 → When: July 22–26'], ['4', '선택지와 본문 문장을 한 단어씩 대조', '매일 밤 ↔ on the last day'], ['5', '바꿔 말한 표현에 주의', 'twice a week = 일주일에 두 번']], cap: '세부 내용 문제 풀이 5단계' } },
    { h: '오답을 만드는 함정 표현',
      p: '출제자는 본문 내용을 살짝 바꿔 틀린 선택지를 만든다. 특히 아래 표현이 나오면 본문과 꼭 대조해야 한다.',
      table: { head: ['함정', '본문', '틀린 선택지'], rows: [['숫자·날짜 바꾸기', 'after a week', '한 달 뒤에'], ['극단 표현 (all, always, only, never)', 'Some live in warm places.', '모두 추운 곳에서만 산다.'], ['주체 바꾸기', 'Her dad paid the rest.', '진우가 전부 냈다.'], ['비교 뒤집기', 'longer than Jun\'s', '준의 것보다 짧다'], ['본문에 없는 내용 더하기', '(언급 없음)', '참가비는 5,000원이다.']], cap: '내용 일치 문제의 함정' },
      warn: '"그럴듯한" 선택지라도 본문에 근거가 없으면 일치하는 것이 아니다.' },
    { h: '안내문·광고문 읽기',
      p: '안내문은 항목별로 정보가 정리되어 있어 빠르게 찾을 수 있다. Who(대상), When(일시), Where(장소), Fee(참가비), Note(주의 사항)를 먼저 확인한다. <span class="hl">Note, *, Please</span> 뒤에는 정원 제한, 마감일, 준비물처럼 문제로 자주 나오는 정보가 있다.',
      ex: [["Fee: 30,000 won (lunch included)", "참가비: 3만 원 (점심 포함)"], ["Note: Sign up by July 15.", "참고: 7월 15일까지 신청하세요."]] },
  ],
  bank: [
    { lv: 1, q: '내용 일치 문제를 풀 때 가장 먼저 할 일로 알맞은 것은?', o: ['본문을 모두 꼼꼼히 해석한다.', '발문과 선택지를 먼저 읽고 핵심어를 확인한다.', '모르는 단어를 사전에서 찾는다.', '글의 제목을 붙인다.'], a: 1, why: '발문(일치/불일치)과 선택지의 핵심어를 먼저 확인해야 본문에서 무엇을 찾을지 알 수 있다.' },
    { lv: 1, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Sam has a sister and a brother. His sister is twelve, and his brother is five. Sam is the oldest. He is fourteen.</div>`, o: ['Sam has two sisters.', "Sam's brother is twelve.", 'Sam is fourteen years old.', 'Sam is the youngest.'], a: 2, why: 'He is fourteen.이라고 했다. 남동생은 다섯 살이고, 샘은 가장 나이가 많다.' },
    { lv: 1, q: `다음 안내문에서 알 수 <b>없는</b> 것은?<div class="passage">Lost Cat!<br>Name: Coco<br>Color: gray with white feet<br>Last seen: near Sunny Park on Monday<br>If you see her, please tell Ms. Yoon at the front desk.</div>`, o: ['고양이 이름', '고양이 색', '마지막으로 본 장소', '고양이 나이'], a: 3, why: '이름(Coco), 색(회색에 흰 발), 장소(Sunny Park 근처)는 있지만 나이는 나오지 않는다.' },
    { lv: 2, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Ella goes swimming every Tuesday and Thursday. She takes lessons at the city pool. Her lessons start at 5 p.m. and end at 6 p.m. She wants to swim in a race next year.</div>`, o: ['Ella는 올해 대회에 나갈 예정이다.', 'Ella는 일주일에 두 번 수영하러 간다.', '수업은 시립 수영장에서 한다.', '수업은 한 시간 동안 한다.'], a: 0, why: 'next year(내년)에 대회에 나가고 싶다고 했다. 시기를 바꾼 함정이다.' },
    { lv: 2, q: `다음 글의 내용과 일치하는 것은?<div class="passage">The school store opens at 8 a.m. and closes at 4 p.m. It sells pens, notebooks, and snacks. It is closed on weekends. Students can pay with cash or a student card.</div>`, o: ['The store opens at 9 a.m.', 'The store sells snacks.', 'The store is open on Saturdays.', 'Students can pay only with cash.'], a: 1, why: 'It sells pens, notebooks, and snacks.라고 했다. ④는 only를 넣어 바꾼 함정이다.' },
    { lv: 2, q: '내용 일치 문제에서 특히 본문과 대조해야 할 함정 표현이 <b>아닌</b> 것은?', o: ['only', 'never', 'and', 'all'], a: 2, why: 'only, never, all처럼 범위를 극단적으로 정하는 표현이 자주 함정이 된다. and는 단순한 연결어이다.' },
    { lv: 3, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Mr. Brown is a science teacher from Australia. He has taught at our school for three years. He loves Korean food, especially kimchi stew. On weekends, he often goes hiking with his students. He plans to go back to Australia next year.</div>`, o: ['브라운 선생님은 호주 출신이다.', '학교에서 3년 동안 가르쳤다.', '주말에는 혼자 등산을 간다.', '내년에 호주로 돌아갈 계획이다.'], a: 2, why: 'with his students라고 했으므로 학생들과 함께 등산을 간다. 주체를 바꾼 함정이다.' },
    { lv: 3, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Our town's library has a new program for teens. Every Wednesday, teens can learn how to make short videos. The program is free, but only twenty students can join. To sign up, visit the front desk by May 3.</div>`, o: ['Only twenty students can join.', 'The program is for adults.', 'The program costs 5,000 won.', 'You can sign up online.'], a: 0, why: 'only twenty students can join이라고 했다. 대상은 10대, 무료이며, 신청은 안내 데스크에서 한다.' },
    { lv: 3, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Penguins are birds, but they cannot fly. Instead, they are excellent swimmers. Their wings work like flippers in the water. Most penguins live in the southern half of the world. Some even live in warm places, not only in cold places.</div>`, o: ['펭귄은 새이다.', '펭귄은 모두 추운 곳에서만 산다.', '펭귄은 날지 못한다.', '펭귄의 날개는 물속에서 지느러미처럼 쓰인다.'], a: 1, why: 'Some even live in warm places라고 했으므로 "모두 추운 곳에서만"은 틀린다. 극단 표현 함정이다.' },
    { lv: 4, q: `다음 안내문의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Summer Science Camp<br>Are you curious about science? Join our summer camp!<br>Who: Middle school students<br>When: July 22–26, 10 a.m. to 3 p.m.<br>Where: City Science Museum<br>Fee: 30,000 won (lunch included)<br>Activities: making robots, doing experiments, and watching the stars on the last night<br>Note: Only 40 students can join. Sign up on our website by July 15.</div>`, o: ['중학생을 대상으로 한다.', '참가비에 점심값이 포함되어 있다.', '매일 밤 별을 관찰한다.', '7월 15일까지 신청해야 한다.'], a: 2, why: '별 관찰은 on the last night(마지막 날 밤)에만 한다.' },
    { lv: 4, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Lee Sora was born in 1995 in a small village. As a child, she loved drawing animals. Because her family was poor, she couldn't take art lessons. Instead, she drew pictures on old newspapers. When she was twenty, she won first prize in a national art contest. Today, she is a famous illustrator who has drawn pictures for more than fifty children's books.</div>`, o: ['그녀는 큰 도시에서 태어났다.', '어렸을 때 미술 수업을 많이 받았다.', '지금까지 열 권의 동화책 그림을 그렸다.', '스무 살에 전국 미술 대회에서 1등을 했다.'], a: 3, why: 'When she was twenty, she won first prize in a national art contest.라고 했다. 작은 마을에서 태어났고, 미술 수업은 받지 못했으며, 50권 이상의 그림을 그렸다.' },
    { lv: 4, q: `다음 글을 통해 알 수 <b>없는</b> 것은?<div class="passage">Dear Neighbors,<br>The water in our apartment building will be turned off this Thursday from 9 a.m. to 1 p.m. because the pipes need to be fixed. Please save some water before 9 a.m. if you need it. The elevator will work as usual. If you have any questions, please call the management office. We are sorry for the trouble.<br>– Sunshine Apartments</div>`, o: ['공사 비용', '단수 요일', '단수 시간', '단수 이유'], a: 0, why: '요일(목요일), 시간(오전 9시~오후 1시), 이유(배관 수리)는 나오지만 공사 비용은 나오지 않는다.' },
    { lv: 5, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Sea otters live in the North Pacific Ocean. They spend most of their lives in the water. Unlike most sea animals, sea otters do not have a thick layer of fat. Instead, they have very thick fur that keeps them warm. They often float on their backs and use rocks to open shellfish. When they sleep, they sometimes hold hands so that they don't drift apart.</div>`, o: ['북태평양에 산다.', '두꺼운 지방층으로 체온을 유지한다.', '돌을 이용해 조개를 깬다.', '잘 때 서로 손을 잡기도 한다.'], a: 1, why: '해달은 두꺼운 지방층이 없고, 대신 아주 빽빽한 털로 체온을 유지한다.' },
    { lv: 5, q: `다음 글의 내용과 일치하는 것은?<div class="passage">Our class asked 30 students how they get to school. Half of them walk. Eight students take the bus, and five ride bikes. The rest come by car with their parents. Interestingly, the students who ride bikes live the farthest from school. The students who walk said they enjoy talking with friends on the way.</div>`, o: ['15명이 버스를 타고 온다.', '자전거를 타는 학생이 가장 적다.', '2명이 부모님 차로 온다.', '걸어오는 학생들이 학교에서 가장 멀리 산다.'], a: 2, why: '30명 중 걷는 학생 15명, 버스 8명, 자전거 5명이므로 나머지 2명이 차로 온다. 가장 적은 것은 차, 가장 멀리 사는 것은 자전거 타는 학생이다.' },
    { lv: 5, q: `다음 글의 내용과 일치하지 <b>않는</b> 것은?<div class="passage">Hi, everyone! Our school festival is coming next Friday. In the morning, there will be a singing contest in the gym. Each class must send at least one team. In the afternoon, clubs will sell food and crafts in the playground. All the money will go to children in need. If it rains, the afternoon events will move to the cafeteria. Don't forget to bring your own cups!</div>`, o: ['축제는 다음 주 금요일에 열린다.', '오전에 체육관에서 노래 대회가 열린다.', '비가 오면 오후 행사는 식당에서 한다.', '반마다 한 팀까지만 노래 대회에 나갈 수 있다.'], a: 3, why: 'at least one team(최소 한 팀)이라고 했으므로 "한 팀까지만"은 틀린다.' },
  ],
});
